제1조 목적 (Purpose) 
 본 보험은 피보험자가 소유한 동산(movable property)을 화재, 도난, 자연재해, 건물 관련 손해 및 우발적 파손으로부터 보호하는 것을 목적으로 한다. 
 보험의 범위: 가전제품, 전자기기, 가구, 자동차 부품, 귀금속, 의류 및 기타 개인 소유 물품 
 계약자의 의무: 보험 가입 시 정확한 보험가액을 신고하고, 보험 기간 중 중대한 위험의 변화를 지체 없이 통지하여야 한다.

제2조 용어의 정의 (Definitions) 
 본 약관에서 사용하는 주요 용어의 정의는 다음과 같다: 
 동산(Movable Property) 가전제품, 전자기기, 가구, 자동차, 귀금속, 의류 등 부동산을 제외한 개인 소유 물품 
 보험가액(Insured Value) 피보험자가 신청한 동산의 평가액으로, SEED_HOUSEHOLD_GOODS의 AVG_TOTAL_VALUE_KRW 기준 
 세그먼트(Segment) A1~A6 (생애주기: 신혼, 유아기, 아동기, 청년기, 중년기, 노년기) + B1~B5 (자산유형: 가전, 전자, 가구, 자동차, 기타)로 구성된 최대 21개 그룹 
 소득구간(Income Bracket) 저소득(LOW), 중소득(MID), 고소득(HIGH), 초고소득(ULTRA)의 4가지 등급 
 리스크등급(Risk Grade) 고위험, 중위험, 저위험, 미산정의 4가지 등급 (RISK_GRADE) 
 복합리스크스코어(Composite Risk Score) 화재, 도난, 기상, 건물 관련 리스크를 통합한 점수 (0-100) 
 기본보험료(Base Premium) 세그먼트별 리스크 평가에 따른 기초 보험료 (AVG_BASE_PREMIUM) 
 조정보험료(Adjusted Premium) 신용도, 세그먼트 계수, 피드백 보정을 반영한 최종 월 보험료 (ADJUSTED_PREMIUM_MONTHLY) 
 손해(Loss) 보험 사건으로 인한 동산의 멸실 또는 훼손으로 피보험자가 입게 되는 경제적 손실
