제3조 보장범위 (Coverage Scope) 
 본 보험이 보장하는 손해의 범위는 다음과 같다: 
 1. 화재 손해 (Fire Damage) 피보험자 소유의 동산이 화재로 인해 입은 직접 손해 (FIRE_RISK_SCORE 반영) 
 2. 도난 손해 (Theft) 피보험자의 거주지 또는 보관 장소에서 도난으로 인해 입은 손해 (THEFT_RISK_SCORE 반영) 
 3. 자연재해 손해 (Natural Disaster) 태풍, 폭우, 폭설, 지진 등 자연재해로 인한 손해 (WEATHER_RISK_SCORE 반영) 
 4. 건물 관련 손해 (Building-related Damage) 건물의 주요 구조 부분의 훼손으로 인해 보관 중인 동산이 입는 손해 (BUILDING_RISK_SCORE 반영) 
 5. 우발적 파손 (Accidental Damage) 피보험자의 고의가 없는 우발적 사고로 인한 동산의 파손, 손상 
 주의: 각 보장은 독립적으로 적용되며, 복수의 보장 사유가 발생한 경우에는 실제 손해액을 한 번만 보상합니다.
