제4조 보험금 산출 (Benefit Calculation) 
 보험금은 다음 공식에 따라 산출된다: 
 보험금 = MIN(실제손해액, 보험가액) × 보상비율 
 여기서: 
 실제손해액: 감정인이 확인한 손해의 실제 금액 
 보험가액: 보험 계약 당시 신고한 동산의 가치 
 보상비율: 세그먼트별 손해율 및 위험도에 따른 차등 비율 (SEGMENT_ASSET_COEFFICIENTS 참조) 
 리스크 등급 보상비율 조건 
 저위험 (LOW) 100% COMPOSITE_RISK_SCORE < 25 
 중위험 (STANDARD) 95% COMPOSITE_RISK_SCORE 25-40 
 고위험 (HIGH) 85% COMPOSITE_RISK_SCORE 40-60 
 극고위험 (CRITICAL) 75% COMPOSITE_RISK_SCORE > 60 
 보험금 지급 조건: 보험금은 보험사고 접수 후 30일 이내 지급하는 것을 원칙으로 합니다. 다만, 추가 확인이 필요한 경우 그 기간을 연장할 수 있습니다.
