제5조 면책사항 (Exclusions) 
 다음의 경우에는 보험금을 지급하지 않는다: 
 1. 고의 또는 중과실 계약자 또는 피보험자의 고의나 중과실로 인한 손해 
 2. 전쟁, 혁명, 내란 등 전쟁, 내란, 테러 행위로 인한 손해 
 3. 핵사고, 핵연쇄반응 핵사고 또는 핵연쇄반응으로 인한 손해 
 4. 자연마모, 부식, 변색 시간의 경과에 따른 자연마모, 부식, 변색 등 
 5. 설계, 제조 결함 동산의 설계 또는 제조 결함으로 인한 손해 
 6. 동물 및 식물의 피해 애완동물이나 해충, 식물로 인한 직접 손해 
 7. 계약자 기재 누락 보험 계약 시 의도적으로 품목을 누락하여 신고한 경우 
 보험료 미납 주의: 보험료를 60일 이상 납부하지 않는 경우, 보험계약은 자동 해제되며 그 이후 발생한 손해에 대해서는 보험금을 지급하지 않습니다.', 'INSURE', '동산종합보험', '동산', NULL, '제2장 보험금의 지급', '제5조', '면책사항', 461, 184, 'high', NULL),
