제6조 보험료 산출 기준 (Premium Calculation Basis) 
 보험료는 INSURE 동적보험엔진의 비선형 5구간 리스크 커브 v1.3을 적용하여 산출된다. 
 복합보험료 계수 = 기본 계수 + 위험도 추가 계수 계수 산출 방식: • LOW_RISK (0-25): 0.85 + (score/25)^0.7 × 0.15 • STANDARD (25-40): 1.00 + (score-25)/100 • ELEVATED (40-60): 1.15 + ((score-40)/20)^1.5 × 0.35 • HIGH (60-80): 1.50 + ((score-60)/20)^1.8 × 0.50 • CRITICAL (80+): min(2.00 + (score-80)×0.02, 2.50) 
 최종 월 보험료 = 기본보험료(AVG_BASE_PREMIUM) × 복합보험료 계수 
 리스크 구간 복합리스크스코어 범위 기본 계수 특징 
 LOW_RISK 0 - 25 0.85 - 1.00 낮은 위험도, 우수한 신용도, 저위험 지역 
 STANDARD 25 - 40 1.00 - 1.15 표준 위험도, 일반적인 신용도 
 ELEVATED 40 - 60 1.15 - 1.50 상승된 위험도, 추가 주의 필요 
 HIGH 60 - 80 1.50 - 2.00 높은 위험도, 특별 심사 대상 
 CRITICAL 80 + 2.00 - 2.50 극도로 높은 위험도, 제한된 인수 
 데이터 베이스 참조: SEED_HOUSEHOLD_GOODS.COMPOSITE_RISK_SCORE는 다음 지표의 가중 평균으로 계산됩니다: - FIRE_RISK_SCORE (가중치 25%) - THEFT_RISK_SCORE (가중치 25%) - WEATHER_RISK_SCORE (가중치 25%) - BUILDING_RISK_SCORE (가중치 25%)
