    ('INSURE_동산종합보험_05_제7조', '[INSURE / 동산종합보험 / 제3장 보험료] 제7조 할인 및 할증', '[INSURE / 동산종합보험 / 제3장 보험료] 제7조 할인 및 할증
제7조 할인 및 할증 (Discounts & Surcharges) 
 기본 보험료에 대해 다음과 같은 할인 및 할증이 적용될 수 있다: 
 1. 신용등급 할인 (Credit Score Discount) • 신용등급 800 이상: 10% 할인 • 신용등급 700-799: 5% 할인 • 신용등급 600-699: 할인 없음 • 신용등급 600 미만: 10% 할증 
 2. 세그먼트 계수 조정 (Segment Coefficient Adjustment) 생애주기 계수(A계수)와 자산유형 계수(B계수)의 평균값으로 세분화된 위험도 반영: 조정계수 = (A계수 + B계수) / 2 
 3. 피드백 보정 (Feedback Adjustment) 계약자의 과거 청구 기록, 성실도, 위험 행동 개선에 따른 동적 보정 (V_FEEDBACK_ADJUSTMENT): 범위: 0.92 - 1.03 (최소 8% 할인 ~ 최대 3% 할증) 
 할인/할증 항목 적용 조건 할인율 
 신용등급 할인 신용점수 800 이상 최대 10% 
 장기계약 할인 3년 이상 연속 계약 최대 5% 
 무사고 할인 최근 3년간 청구 기록 없음 최대 15% 
 복합보험 할인 2개 이상의 보험상품 가입 최대 8% 
 위험도 할증 COMPOSITE_RISK_SCORE > 60 최대 20% 
 유의사항: 할인과 할증이 중복 적용될 수 있으며, 최종 보험료는 기본보험료의 50% 이상 200% 이하의 범위로 제한됩니다.
