제8조 보험료 납부 (Premium Payment) 
 보험료는 다음과 같이 납부한다: 
 1. 납부 방식 • 월납: 매월 일정 날짜에 납부 • 연납: 연간 보험료를 일시에 납부 (3% 할인 적용) 
 2. 납부 기한 월납의 경우 매월 지정 날짜 이내, 연납의 경우 계약 체결일로부터 30일 이내 
 3. 연체료 보험료를 15일 초과 납부하지 않는 경우, 연체료 년 5%가 부과됩니다 
 4. 보험료 환급 계약 해제 시, 보험료는 경과 기간에 해당하는 보험료를 차감하고 환급합니다. 단, 손해가 발생한 경우에는 환급하지 않습니다. 
 자동이체 등록 시 특별 혜택: 은행 자동이체로 보험료를 납부하는 경우, 추가로 2% 할인이 적용됩니다.', 'INSURE', '동산종합보험', '동산', NULL, '제3장 보험료', '제8조', '보험료 납부', 395, 158, 'high', NULL),
