제9조 계약 체결 (Policy Issuance) 
 보험계약은 계약자의 청약과 보험사의 승낙으로 성립한다. 
 1. 청약 절차 계약자는 보험사가 정한 청약서에 다음 사항을 기재하여 제출합니다: • 계약자 및 피보험자의 기본정보 • 동산의 종류, 수량, 가액 • 보관 위치 및 사용 용도 • 과거 보험 청구 이력 • 기타 특별약관 여부 
 2. 승낙 및 보험증권 발급 보험사는 청약 접수 후 5일 이내 승낙 여부를 결정하고, 승낙 시 보험증권을 발급합니다. 다만 위험 평가를 위해 추가 서류를 요청할 수 있습니다. 
 3. 청약 철회 계약자는 보험증권 수령 후 15일 이내에 청약을 철회할 수 있으며, 손해가 없을 경우 납부한 보험료를 전액 환급받을 수 있습니다. 
 온라인 가입: INSURE 시스템을 통한 온라인 가입의 경우, 즉시 보험증권이 발급되며 전자문서로 제공됩니다.', 'INSURE', '동산종합보험', '동산', NULL, '제4장 보험계약', '제9조', '계약 체결', 474, 189, 'high', NULL),
