제10조 계약 기간 (Policy Period) 
 보험계약의 기간은 다음과 같이 정한다: 
 1. 기본 기간 보험기간은 1년입니다. 보험기간은 보험증권에 기재된 개시일을 기준으로 시작됩니다. 
 2. 자동갱신 계약이 만료되는 날로부터 30일 이전에 계약자가 갱신하지 않겠다는 의사를 통지하지 않으면 1년의 기간으로 자동갱신됩니다. 
 3. 기간 변경 계약자는 보험사의 동의 하에 보험기간을 변경할 수 있습니다. 기간을 단축하는 경우, 경과 기간에 해당하는 보험료를 차감하고 환급합니다. 
 장기계약 특혜: 3년 이상 지속적으로 계약을 갱신하는 고객은 ''우수 계약자'' 등급으로 상향되어 추가 할인을 받을 수 있습니다.', 'INSURE', '동산종합보험', '동산', NULL, '제4장 보험계약', '제10조', '계약 기간', 385, 154, 'high', NULL),
