제11조 해약 및 환급 (Cancellation & Refund) 
 보험계약의 해약과 환급은 다음과 같이 처리된다: 
 1. 계약자 청구 해약 계약자는 언제든지 보험사에 해약을 청구할 수 있습니다. 다만, 손해가 발생한 이후의 해약은 인정되지 않습니다. 
 2. 보험사 강제 해약 보험료를 60일 이상 납부하지 않거나, 위험이 현저히 증가한 경우 보험사는 예고 후 계약을 해약할 수 있습니다. 
 3. 환급금 계산 환급금 = 납입보험료 - (기본보험료 × 경과개월수/12) - 손해발생 시 보상액 단, 환급금이 0원 이하인 경우에는 환급하지 않습니다. 
 4. 환급 기한 환급금은 해약 청구 접수 후 10일 이내에 지급합니다. 
 주의: 해약 후 동일한 동산에 대한 재가입을 신청할 경우, 최소 30일의 대기 기간이 필요할 수 있습니다.', 'INSURE', '동산종합보험', '동산', NULL, '제4장 보험계약', '제11조', '해약 및 환급', 455, 182, 'high', NULL),
