제13조 분쟁조정 (Complaint Resolution) 
 본 보험계약에 관하여 분쟁이 발생한 경우는 다음과 같이 처리한다: 
 1단계: 보험사 민원 담당 계약자는 먼저 보험사의 고객센터(☎ 1588-0000) 또는 민원 담당부서에 민원을 제기합니다. 보험사는 접수 후 10일 이내에 처리 결과를 통지합니다. 
 2단계: 금융감독원 분쟁조정 보험사의 처리 결과에 이의가 있는 경우, 금융감독원 분쟁조정위원회에 분쟁조정을 신청할 수 있습니다. • 신청 기한: 분쟁 발생 후 2년 이내 • 신청비용: 무료 • 연락처: www.fss.or.kr 또는 ☎ 1332 
 3단계: 소송 분쟁조정 결과에 이의가 있거나 조정을 거치지 않으려는 경우, 관할 법원에 민사소송을 제기할 수 있습니다. 
 관할 법원: 본 보험계약 분쟁에 관한 소송은 계약자의 주소지, 보험사의 주소지, 또는 피보험자의 주소지를 관할하는 법원에서 제기할 수 있습니다.', 'INSURE', '동산종합보험', '동산', NULL, '제6장 분쟁해결', '제13조', '분쟁조정', 504, 201, 'high', NULL),
