제11조 손해액의 조사결정
회사가 보상할 손해액은 그 손해가 생긴 때와 곳에서의 보험가액에 따라 계산합니다.

제12조 현물보상
회사는 손해의 일부 또는 전부에 대하여 재건축, 수리 또는 현물의 보상으로서 보험금의 지급
에 대신할 수 있습니다.

제13조 잔존물
회사가 제3조(보상하는 손해) 제1항의 보험금을 지급하고 잔존물을 취득할 의사표시를 하는 경
우에는 그 잔존물은 회사의 소유가 됩니다.

제14조 대위권
① 회사가 보험금을 지급한 때(현물보상한 경우를 포함합니다)에는 회사는 지급한 보험금 한도
내에서 계약자 또는 피보험자가 제3자에 대하여 가지는 손해배상청구권을 취득합니다. 다
만, 회사가 보상한 금액이 피보험자가 입은 손해의 일부인 경우에는 피보험자의 권리를 침
해하지 않는 범위 내에서 그 권리를 취득합니다.
② 계약자 또는 피보험자는 제1항에 의하여 회사가 취득한 권리를 행사하거나 지키는 것에 관
하여 필요한 조치를 하여야 하며 또한 회사가 요구하는 증거 및 서류를 제출하여야 합니다.
③ 회사는 제1항 및 제2항에 불구하고 타인을 위한 계약의 경우에는 계약자에 대한 대위권을
포기합니다.
④ 회사는 제1항에 따른 권리가 계약자 또는 피보험자와 생계를 같이 하는 가족에 대한 것인
경우에는 그 권리를 취득하지 못합니다. 다만, 손해가 그 가족의 고의로 인하여 발생한 경
우에는 그 권리를 취득합니다.
⑤ 회사는 제1항에 따른 권리가 계약자 또는 피보험자와 임대차계약을 체결하는 등 거주를 허
락한 자(이하 ‘임차인등’)에 대한 것으로서, 임차인등이 보험료를 납부하는 경우 임차인등
및 이들과 생계를 같이하는 가족에 대한 대위권을 포기합니다. 다만, 손해가 임차인등 및
