제16조 계약 후 알릴 의무
① 계약을 맺은 후 보험의 목적에 아래와 같은 사실이 생긴 경우에는 계약자나 피보험자는 지
체없이 서면으로 회사에 알리고 보험증권에 확인을 받아야 합니다.
1. 이 계약에서 보장하는 위험과 동일한 위험을 보장하는 계약을 다른 보험자와 체결하고자
할 때 또는 이와 같은 계약이 있음을 알았을 때
2. 양도할 때
3. 보험의 목적 또는 보험의 목적을 수용하는 건물의 구조를 변경, 개축, 증축하거나 계속하
여 15일 이상 수선할 때
4. 보험의 목적 또는 보험의 목적을 수용하는 건물의 용도를 변경함으로써 위험이 변경되는
경우
5. 보험의 목적 또는 보험의 목적이 들어있는 건물을 계속하여 30일 이상 비워 두거나 휴업
하는 경우
6. 다른 곳으로 옮길 때
7. 위험이 뚜렷이 변경되거나 변경되었음을 알았을 때
② 회사는 제1항에 따라 위험이 감소된 경우에는 그 차액보험료를 돌려드리며, 위험이 증가된
경우에는 통지를 받은 날부터 1개월 이내에 보험료의 증액을 청구하거나 계약을 해지할 수
있습니다.
③ 계약자 또는 피보험자는 주소 또는 연락처가 변경된 경우에는 지체없이 이를 회사에 알려
야 합니다. 다만, 계약자 또는 피보험자가 알리지 않은 경우 회사가 알고 있는 최종의 주소
또는 연락처로 등기우편 등 우편물에 대한 기록이 남는 방법으로 회사가 알린 사항은 일반
적으로 도달에 필요한 기간이 지난 때에는 계약자 또는 피보험자에게 도달한 것으로 봅니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제3관 계약자의 계약 전 알릴 의무 등', '제15조~제16조', '계약 전 알릴 의무', 868, 347, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제17조제18조제19조', '[KB손해보험 / 아파트종합보험 / 제3관 계약자의 계약 전 알릴 의무 등] 제17조~제18조~제19조 사기에 의한 계약', '[KB손해보험 / 아파트종합보험 / 제3관 계약자의 계약 전 알릴 의무 등] 제17조~제18조~제19조 사기에 의한 계약
계약자, 피보험자 또는 이들의 대리인의 사기에 의하여 계약이 성립되었음을 회사가 증명하는 경
우에는 계약일부터 5년 이내(사기사실을 안 날부터 1개월 이내)에 계약을 취소할 수 있습니다.

제18조 보험계약의 성립
① 계약은 계약자의 청약과 회사의 승낙으로 이루어집니다.
② 회사는 계약의 청약을 받고 보험료 전액 또는 제1회 보험료(이하 ‘제1회 보험료 등’이라 합
니다)를 받은 경우에는 청약일부터 30일 이내에 승낙 또는 거절의 통지를 하며 통지가 없
으면 승낙한 것으로 봅니다.
③ 회사가 청약을 승낙한 때에는 지체 없이 보험증권을 계약자에게 교부하여 드리며, 청약을
거절한 경우에는 거절통지와 함께 받은 금액을 계약자에게 돌려드립니다.
④ 이미 성립한 계약을 연장하거나 변경하는 경우에는 회사는 보험증권에 그 사실을 기재함으
로써 보험증권의 교부에 대신할 수 있습니다.

제19조 청약의 철회
① 계약자는 보험증권을 받은 날부터 15일 이내에 그 청약을 철회할 수 있습니다. 다만, 의무보
험의 경우에는 철회의사를 표시한 시점에 동종의 다른 의무보험에 가입된 경우에만 철회할 수
있으며, 보험기간이 90일 이내인 계약 또는 전문금융소비자가 체결한 계약은 청약을 철회할
수 없습니다.
【전문금융소비자】
보험계약에 관한 전문성, 자산규모 등에 비추어 보험계약에 따른 위험감수능력이 있는 자
로서, 국가, 지방자치단체, 한국은행, 금융회사, 주권상장법인 등을 포함하며 ｢금융소비자
보호에 관한 법률｣ 제2조(정의) 제9호에서 정하는 전문금융소비자를 말합니다.
【일반금융소비자】
전문금융소비자가 아닌 계약자를 말합니다.
② 제1항에도 불구하고 청약한 날부터 30일(단, 만 65세 이상의 계약자가 통신수단 중 전화를
이용하여 체결한 경우 45일)만 이 초과된 계약은 청약을 철회할 수 없습니다.
③ 청약철회는 계약자가 전화로 신청하거나, 철회의사를 표시하기 위한 서면, 전자우편, 휴대전화
문자메시지 또는 이에 준하는 전자적 의사표시(이하 ‘서면 등’이라 합니다)를 발송한 때 효력이
발생합니다. 계약자는 서면 등을 발송한 때에 그 발송 사실을 회사에 지체없이 알려야 합니다.
④ 계약자가 청약을 철회한 때에는 회사는 청약의 철회를 접수한 날부터 3영업일 이내에 납입
한 보험료를 계약자에게 돌려드리며, 보험료 반환이 늦어진 기간에 대하여는 ‘보험개발원이
공시하는 보험계약대출이율’을 연단위 복리로 계산한 금액을 더하여 지급합니다. 다만, 계약
자가 제1회 보험료 등을 신용카드로 납입한 계약의 청약을 철회하는 경우에 회사는 청약의
철회를 접수한 날부터 3영업일 이내에 해당 신용카드회사로 하여금 대금청구를 하지 않도록 해야
하며, 이 경우 회사는 보험료를 반환한 것으로 봅니다.
⑤ 청약을 철회할 때에 이미 보험금 지급사유가 발생하였으나 계약자가 그 보험금 지급사유가
발생한 사실을 알지 못한 경우에는 청약철회의 효력은 발생하지 않습니다.
⑥ 제1항에서 보험증권을 받은 날에 대한 다툼이 발생한 경우 회사가 이를 증명하여야 합니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제3관 계약자의 계약 전 알릴 의무 등', '제17조~제18조~제19조', '사기에 의한 계약', 1543, 617, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제20조', '[KB손해보험 / 아파트종합보험 / 제4관 보험계약의 성립과 유지] 제20조 약관 교부 및 설명의무 등', '[KB손해보험 / 아파트종합보험 / 제4관 보험계약의 성립과 유지] 제20조 약관 교부 및 설명의무 등
① 회사는 계약자가 청약할 때에 계약자에게 약관의 중요한 내용을 설명하여야 하며, 청약 후
에 다음 각 호의 방법 중 계약자가 원하는 방법을 확인하여 지체 없이 약관 및 계약자 보관
용 청약서를 제공하여 드립니다. 만약, 회사가 전자우편 및 전자적 의사표시로 제공한 경우 계약
자 또는 그 대리인이 약관 및 계약자 보관용 청약서 등을 수신하였을 때에는 해당 문서를
드린 것으로 봅니다.
1. 서면교부
2. 우편 또는 전자우편
3. 휴대전화 문자메시지 또는 이에 준하는 전자적 의사표시
【약관의 중요한 내용】
금융소비자 보호에 관한 법률 제19조(설명의무)에 따른 중요한 사항은 다음의 내용을 말합
니다.
- 청약의 철회에 관한 사항
- 지급한도, 면책사항, 감액지급 사항 등 보험금 지급제한 조건
- 고지의무 위반의 효과
- 계약의 취소 및 무효에 관한 사항
- 해약환급금에 관한 사항
- 분쟁조정절차에 관한 사항
- 그 밖에 약관에 기재된 보험계약의 중요사항
② 제1항과 관련하여 통신판매계약의 경우, 회사는 계약자가 가입한 특약만 포함한 약관을 드
리며, 전화를 이용하여 체결하는 계약은 계약자의 동의를 얻어 다음의 중 한 가지 방법으로
약관의 중요한 내용을 설명할 수 있습니다.
1. 전화를 이용하여 청약내용, 보험료납입, 보험기간, 계약 전 알릴 의무, 약관의 중요한 내
용 등 계약을 체결하는 데 필요한 사항을 질문 또는 설명하는 방법. 이 경우 계약자의
답변과 확인내용을 음성 녹음함으로써 약관의 중요한 내용을 설명한 것으로 봅니다.
【통신판매계약】
전화·우편·인터넷 등 통신수단을 이용하여 체결하는 계약을 말합니다.
③ 회사가 제1항에 따라 제공될 약관 및 계약자 보관용 청약서를 청약할 때 계약자에게 전달
하지 않거나 약관의 중요한 내용을 설명하지 않은 때 또는 계약을 체결할 때 계약자가 청
약서에 자필서명을 하지 않은 때에는 계약자는 계약이 성립한 날부터 3개월 이내에 계약을
취소할 수 있습니다.
【자필서명】
날인(도장을 찍음) 및 전자서명법 제2조 제2호에 따른 전자서명을 포함합니다.
④ 제3항에 따라 계약이 취소된 경우에는 회사는 이미 납입한 보험료를 계약자에게 돌려 드리
며, 보험료를 받은 기간에 대하여 ‘보험개발원이 공시하는 보험계약대출이율’을 연단위 복
리로 계산한 금액을 더하여 지급합니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제4관 보험계약의 성립과 유지', '제20조', '약관 교부 및 설명의무 등', 1191, 476, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제21조제22조', '[KB손해보험 / 아파트종합보험 / 제4관 보험계약의 성립과 유지] 제21조~제22조 계약의 무효', '[KB손해보험 / 아파트종합보험 / 제4관 보험계약의 성립과 유지] 제21조~제22조 계약의 무효
계약을 맺을 때에 보험의 목적에 이미 사고가 발생하였을 경우 이 계약은 무효로 합니다. 다
만, 회사의 고의 또는 과실로 계약이 무효로 된 경우와 회사가 승낙 전에 무효임을 알았거나
알 수 있었음에도 불구하고 보험료를 반환하지 않은 경우에는 보험료를 납입한 날의 다음날부
터 반환일까지의 기간에 대하여 회사는 보험개발원이 공시하는 보험계약대출이율을 연단위 복
리로 계산한 금액을 더하여 돌려 드립니다.

제22조 계약내용의 변경 등
① 계약자는 회사의 승낙을 얻어 다음의 사항을 변경할 수 있습니다. 이 경우 승낙을 서면 등
으로 알리거나 보험증권의 뒷면에 기재하여 드립니다.
1. 보험종목
2. 보험기간
3. 보험료 납입주기, 납입방법 및 납입기간
4. 계약자, 피보험자
5. 보험가입금액, 보험료 등 기타 계약의 내용
② 회사는 계약자가 제1회 보험료 등을 납입한 때부터 1년 이상 지난 유효한 계약으로서 그
보험종목의 변경을 요청할 때에는 회사의 사업방법서에서 정하는 방법에 따라 이를 변경하
여 드립니다.
③ 회사는 계약자가 제1항 제5호의 규정에 의하여 보험가입금액을 감액하고자 할 때에는 그
감액된 부분은 계약이 해지된 것으로 보며, 제33조(보험료의 환급)에 따라 보험료를 계약자
에게 지급합니다.
④ 회사는 제1항에 따라 계약자를 변경한 경우, 변경된 계약자에게 보험증권 및 약관을 교부하
고 변경된 계약자가 요청하는 경우 약관의 중요한 내용을 설명하여 드립니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제4관 보험계약의 성립과 유지', '제21조~제22조', '계약의 무효', 770, 308, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제23조제24조제25조', '[KB손해보험 / 아파트종합보험 / 제4관 보험계약의 성립과 유지] 제23조~제24조~제25조 보험의 목적에 대한 조사', '[KB손해보험 / 아파트종합보험 / 제4관 보험계약의 성립과 유지] 제23조~제24조~제25조 보험의 목적에 대한 조사
회사는 보험목적에 대한 위험상태를 조사하기 위하여 보험기간 중 언제든지 보험의 목적 또는
이들이 들어 있는 건물이나 구내를 조사할 수 있습니다.

제24조 타인을 위한 계약
① 계약자는 타인을 위한 계약을 체결하는 경우에 그 타인의 위임이 없는 때에는 반드시 이를
회사에 알려야 하며, 이를 알리지 않았을 때에는 그 타인은 이 계약이 체결된 사실을 알지
못하였다는 사유로 회사에 이의를 제기할 수 없습니다.
② 타인을 위한 계약에서 보험사고가 발생한 경우에 계약자가 그 타인에게 보험사고의 발생으
로 생긴 손해를 배상한 때에는 계약자는 그 타인의 권리를 해하지 않는 범위 안에서 회사
에 보험금의 지급을 청구할 수 있습니다.
【타인을 위한 계약】
계약자가 타인의 이익을 위하여 자기의 이름으로 체결하는 보험계약을 말합니다.

제25조 제1회 보험료 등 및 회사의 보장개시
① 회사는 계약의 청약을 승낙하고 제1회 보험료 등을 받은 때부터 이 약관이 정한 바에 따라
보장을 합니다.
② 회사가 계약자로부터 계약의 청약과 함께 제1회 보험료 등을 받은 경우에 그 청약을 승낙
하기 전에 계약에서 정한 보험금 지급사유가 생긴 때에는 회사는 계약상의 보장을 합니다.
③ 제2항의 규정에도 불구하고 회사는 다음 중 한 가지에 해당되는 경우에는 보장을 하지 않
습니다.
1. 제15조(계약 전 알릴 의무)의 규정에 의하여 계약자 또는 피보험자가 회사에 알린 내용
이 보험금 지급사유의 발생에 영향을 미쳤음을 회사가 증명하는 경우
2. 제4조(보상하지 않는 손해), 제17조(사기에 의한 계약), 제21조(계약의 무효) 또는 제30
조(계약의 해지)의 규정을 준용하여 회사가 보장을 하지 않을 수 있는 경우
④ 계약자가 제1회 보험료 등을 자동이체 또는 신용카드로 납입하는 경우에는 자동이체신청
및 신용카드매출 승인에 필요한 정보를 회사에 제공한 때가 제1회 보험료 등을 납입한 때
가 되나, 계약자의 책임있는 사유로 자동이체 또는 매출승인이 불가능한 경우에는 제1회
보험료 등이 납입되지 않은 것으로 봅니다.
⑤ 계약이 갱신되는 경우에는 제1항 내지 제3항에 의한 보장은 기존 계약에 의한 보장이 종료
하는 때부터 적용합니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제4관 보험계약의 성립과 유지', '제23조~제24조~제25조', '보험의 목적에 대한 조사', 1139, 455, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제26조제27조', '[KB손해보험 / 아파트종합보험 / 제5관 보험료의 납입] 제26조~제27조 제2회 이후 보험료의 납입', '[KB손해보험 / 아파트종합보험 / 제5관 보험료의 납입] 제26조~제27조 제2회 이후 보험료의 납입
계약자는 제2회 이후의 보험료를 납입기일까지 납입하여야 하며, 회사는 계약자가 보험료를 납
입한 경우에는 영수증을 발행하여 드립니다. 다만, 금융회사(우체국을 포함합니다)를 통하여 보
험료를 납입한 경우에는 그 금융회사 발행 증빙서류를 영수증으로 대신합니다.
【납입기일】
계약자가 제2회 이후의 보험료를 납입하기로 한 날을 말합니다.

제27조 보험료의 납입이 연체되는 경우 납입최고[독촉]와 계약의 해지
① 계약자가 제2회 이후의 보험료를 납입기일까지 납입하지 않아 보험료 납입이 연체 중인 경
우에는, 회사는 14일(보험기간이 1년 미만인 경우에는 7일) 이상의 기간을 납입최고(독촉)
기간으로 정하여 계약자(타인을 위한 계약의 경우 그 특정된 타인을 포함합니다)에게 다음
의 내용을 서면(등기우편 등), 전화(음성녹음) 또는 전자문서 등으로 알려드립니다. 다만,
계약이 해지되기 전에 발생한 보험금 지급사유에 대하여 회사는 계약상의 보장을 합니다.
1. 납입최고(독촉)기간 내에 연체보험료를 납입하여야 한다는 내용
2. 납입최고(독촉)기간이 끝나는 날까지 보험료를 납입하지 않을 경우 그 끝나는 날의 다음
날에 계약이 해지된다는 내용
② 제1항의 납입최고(독촉)기간은 납입최고(독촉)의 통지가 계약자(타인을 위한 계약의 경우에
는 그 특정된 타인을 포함)에게 도달한 날부터 시작되며, 납입최고(독촉)기간의 마지막 날
이 영업일이 아닌 때에는 최고(독촉)기간은 그 다음 날까지로 합니다.
③ 회사가 제1항에 의한 납입최고(독촉) 등을 전자문서로 안내하고자 할 경우에는 계약자의 서
면에 의한 동의를 얻어 수신확인을 조건으로 전자문서를 송신하여야 하며, 계약자가 전자문
서에 대하여 수신을 확인하기 전까지는 그 전자문서는 송신되지 않은 것으로 봅니다. 회사
는 전자문서가 수신되지 않은 것으로 확인되는 경우에는 제1항의 납입최고(독촉)기간을 설
정하여 제1항에서 정한 내용을 서면(등기우편 등) 또는 전화(음성녹음)로 다시 알려 드립니다.
④ 회사가 제1항에 따른 납입최고(독촉) 등을 전화(음성녹음)로 안내하고자 할 때 다음 각 호
의 요건을 모두 충족하는 경우에 「보험업감독규정」 제4-36조 제3항에 따른 전자적 상품
설명장치를 활용할 수 있습니다.
1. 계약자에게 전자적 상품설명장치를 활용하여 제1항에 따른 납입최고(독촉) 등을 한다는
사실을 미리 안내하고 동의를 받을 것
2. 전자적 상품설명장치를 활용하여 안내한 납입최고(독촉) 등을 계약자가 모두 수신하고
이해하였음을 확인할 것
3. 계약자가 질의를 하거나 추가적인 설명을 요청하는 등 전자적 상품설명장치의 활용을
중단할 것을 요구하는 경우, 회사는 전화 (음성녹음) 방법으로 전환하여 제1항에 따른
납입최고(독촉) 등을 실시할 것
4. 전자적 상품설명장치에 안내의 속도와 음량을 조절할 수 있는 기능을 갖출 것
5. 제3호 및 제4호의 내용에 관한 사항을 계약자에게 안내할 것
⑤ 제1항에 따라 계약이 해지된 경우에는 제33조(보험료의 환급)에 따라 보험료를 계약자에게
지급합니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제5관 보험료의 납입', '제26조~제27조', '제2회 이후 보험료의 납입', 1541, 616, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제28조', '[KB손해보험 / 아파트종합보험 / 제5관 보험료의 납입] 제28조 보험료의 납입을 연체하여 해지된 계약의 부활[효력회복]', '[KB손해보험 / 아파트종합보험 / 제5관 보험료의 납입] 제28조 보험료의 납입을 연체하여 해지된 계약의 부활[효력회복]
① 제27조(보험료의 납입이 연체되는 경우 납입최고[독촉]와 계약의 해지)에 따라 계약이 해지
되었으나 계약자가 제33조(보험료의 환급)에 따라 보험료를 돌려받지 않은 경우 계약자는
해지된 날부터 3년 이내에 회사가 정한 절차에 따라 계약의 부활(효력회복)을 청약할 수 있
습니다. 이 경우 회사가 그 청약을 승낙한 때에는 계약자는 부활(효력회복)을 청약한 날까
지의 연체된 보험료에 보험개발원이 공시하는 월평균 정기예금이율 + 1% 범위내에서 각
상품별로 회사가 정하는 이율로 계산한 금액을 더하여 납입하여야 합니다.
② 제1항에 따라 해지계약을 부활(효력회복)하는 경우에는 제15조(계약 전 알릴의무), 제17조
(사기에 의한 계약), 제18조(보험계약의 성립), 제25조(제1회 보험료 등 및 회사의 보장개
시) 및 제30조(계약의 해지)의 규정을 준용합니다. 이 때 회사는 해지 전 발생한 보험금 지
급사유를 이유로 부활(효력회복)을 거절하지 않습니다.
③ 제1항에서 정한 계약의 부활이 이루어진 경우라도 계약자 또는 피보험자가 최초 계약 청약
시(2회 이상 부활이 이루어진 경우 종전 모든 부활 청약 포함) 제15조(계약 전 알릴의무)를
위반한 경우에는 제30조(계약의 해지) 제3항이 적용됩니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제5관 보험료의 납입', '제28조', '보험료의 납입을 연체하여 해지된 계약의 부활[효력회복]', 688, 275, 'high', NULL);

-- 배치 2/13
