    (CHUNK_ID, CONTEXT, CHUNK_TEXT, INSURER, PRODUCT, CATEGORY, SECTION, CHAPTER, ARTICLE_NUMBER, ARTICLE_TITLE, CHAR_LEN, APPROX_TOKENS, DOMAIN_PRIORITY, SQL_REFERENCES)
VALUES
    ('KB손해보험_아파트종합보험_00_제29조', '[KB손해보험 / 아파트종합보험 / 제5관 보험료의 납입] 제29조 강제집행 등으로 인하여 해지된 계약의 특별부활[효력회복]', '[KB손해보험 / 아파트종합보험 / 제5관 보험료의 납입] 제29조 강제집행 등으로 인하여 해지된 계약의 특별부활[효력회복]
① 타인을 위한 계약의 경우 제33조(보험료의 환급)에 따른 계약자의 환급금 청구권에 대한 강
제집행, 담보권실행, 국세 및 지방세 체납처분절차에 의해 계약이 해지된 경우에는, 회사는
해지 당시의 피보험자가 계약자의 동의를 얻어 계약 해지로 회사가 채권자에게 지급한 금
액을 회사에게 지급하고 제22조(계약내용의 변경 등) 제1항의 절차에 따라 계약자 명의를
피보험자로 변경하여 계약의 특별부활(효력회복)을 청약할 수 있음을 피보험자에게 통지하
여야 합니다.
② 회사는 제1항에 의한 계약자 명의변경 신청 및 계약의 특별부활(효력회복) 청약을 승낙하
며, 계약은 청약한 때부터 특별부활(효력회복) 됩니다.
③ 회사는 제1항의 통지를 계약이 해지된 날부터 7일 이내에 하여야 합니다. 다만, 회사의 통
지가 7일을 지나서 도달하고 이후 피보험자가 제1항에 의한 계약자 명의변경 신청 및 계약
의 특별부활(효력회복)을 청약한 경우에는 계약이 해지된 날부터 7일이 되는 날에 특별부활
(효력회복) 됩니다.
④ 피보험자는 통지를 받은 날부터 15일 이내에 제1항의 절차를 이행할 수 있습니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제5관 보험료의 납입', '제29조', '강제집행 등으로 인하여 해지된 계약의 특별부활[효력회복]', 621, 248, 'high', NULL),
    ('KB손해보험_아파트종합보험_00_제30조', '[KB손해보험 / 아파트종합보험 / 제6관 계약의 해지 및 보험료의 환급 등] 제30조 계약의 해지', '[KB손해보험 / 아파트종합보험 / 제6관 계약의 해지 및 보험료의 환급 등] 제30조 계약의 해지
① 계약자는 손해가 발생하기 전에는 언제든지 계약을 해지할 수 있습니다. 다만 타인을 위한
계약의 경우에는 계약자는 그 타인의 동의를 얻거나 보험증권을 소지한 경우에 한하여 계
약을 해지할 수 있습니다.
② 회사는 계약자 또는 피보험자의 고의로 손해가 발생한 경우 이 계약을 해지할 수 있습니다.
③ 회사는 아래와 같은 사실이 있을 경우에는 손해의 발생여부에 관계없이 그 사실을 안 날부
터 1개월 이내에 이 계약을 해지할 수 있습니다.
1. 계약자, 피보험자 또는 이들의 대리인이 제15조(계약 전 알릴 의무)에도 불구하고 고의
또는 중대한 과실로 중요한 사항에 대하여 사실과 다르게 알린 때
2. 뚜렷한 위험의 변경 또는 증가와 관련된 제16조(계약 후 알릴 의무)에서 정한 계약 후
알릴 의무를 이행하지 않았을 때
④ 제3항 제1호의 경우에도 불구하고 다음 중 하나에 해당하는 경우에는 회사는 계약을 해지
할 수 없습니다.
1. 회사가 계약 당시에 그 사실을 알았거나 과실로 인하여 알지 못하였을 때
2. 회사가 그 사실을 안 날부터 1개월 이상 지났거나 또는 제1회 보험료 등을 받은 때부터
보험금 지급사유가 발생하지 않고 2년이 지났을 때
3. 계약을 체결한 날부터 3년이 지났을 때
4. 보험을 모집한 자(이하 “보험설계사 등”이라 합니다)가 계약자 또는 피보험자에게 알릴
기회를 주지 않았거나 계약자 또는 피보험자가 사실대로 알리는 것을 방해한 경우, 계약
자 또는 피보험자에게 사실대로 알리지 않게 하였거나 부실한 사항을 알릴 것을 권유했을
때. 다만, 보험설계사 등의 행위가 없었다 하더라도 계약자 또는 피보험자가 사실대로 알
리지 않거나 부실한 사항을 알렸다고 인정되는 경우에는 계약을 해지할 수 있습니다.
⑤ 제3항에 의한 계약의 해지는 손해가 생긴 후에 이루어진 경우에도 회사는 그 손해를 보상
하여 드리지 않습니다. 그러나 손해가 제3항 제1호 및 제2호의 사실로 생긴 것이 아님을
