보험자의 고의 또는 중대한 과실로 무효가 된 때에는 보험료를 돌려드리지 않습니다.
② 보험기간이 1년을 초과하는 계약이 무효 또는 효력상실인 경우에는 무효 또는 효력상실의
원인이 생긴 날 또는 해지일이 속하는 보험년도의 보험료는 위 제1항의 규정을 적용하고
