③ 회사가 보험금 지급여부 및 지급금액에 관하여 현저하게 공정을 잃은 합의로 계약자 또는
피보험자에게 손해를 가한 경우에도 회사는 제2항에 따라 손해를 배상할 책임을 집니다.
【설명】
현저하게 공정을 잃은 합의란 사회통념상 현저하게 타당성을 잃은 합의를 말합니다.

제40조 개인정보보호
