예금자보호제도란 예금자보호법에 의해 설립된 예금보험공사가 평소에 금융회사로부터
보험료를 받아 기금을 적립한 후, 금융회사가 영업정지나 파산 등으로 예금을 지급할 수
없게 되면 금융회사를 대신하여 예금을 지급하는 제도를 말합니다.
이 보험계약은 예금자보호법에 따라 해약환급금(또는 만기 시 보험금)에 기타지급금을 합
한 금액이 1인당 “1억원까지”(본 보험회사의 여타 보호 상품과 합산) 보호됩니다. 이와
별도로 본 보험회사 보호상품의 사고보험금을 합산한 금액이 1인당 “1억원까지” 보호됩
니다. 다만, 보험계약자 및 보험료 납부자가 법인인 보험계약의 경우에는 보호되지 않습
니다.', 'KB손해보험', '아파트종합보험', '동산', 'KB아파트화재보험 보통약관', '제7관 분쟁의 조정 등', '제41조~제42조', '준거법', 551, 220, 'high', NULL),
