에 기재된 보상한도액내에서 보상
③ 보험금의 청구 및 지급방법은 동법 시행령 제8조를 따릅니다.', 'KB손해보험', '아파트종합보험', '동산', '지진위험 특별약관', NULL, '제5조', '보험금의 지급과 보상한도', 845, 338, 'high', NULL),
    ('KB손해보험_아파트종합보험_05_제6조', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제6조 손해방지의무', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제6조 손해방지의무
① 보험사고가 생긴 때에는 계약자 또는 피보험자는 아래의 사항을 이행하여야 합니다.
1. 손해의 방지 또는 경감을 위하여 노력하는 일(피해자에 대한 응급처치, 긴급호송 또는 그
밖의 긴급조치를 포함합니다)
2. 제3자로부터 손해의 배상을 받을 수 있는 경우에는 그 권리를 지키거나 행사하기 위한
필요한 조치를 취할 일
3. 손해배상책임의 전부 또는 일부에 관하여 지급(변제), 승인 또는 화해를 하거나 소송, 중
재 또는 조정을 제기하거나 신청하고자 할 경우에는 미리 회사의 동의를 받는 일
② 계약자 또는 피보험자가 정당한 이유 없이 제1항의 의무를 이행하지 않았을 때에는 제2조
(보상하는 손해)에 의한 손해에서 다음의 금액을 뺍니다.
1. 제1항 제1호의 경우에는 그 노력을 하였더라면 손해를 방지 또는 경감할 수 있었던 금액
2. 제1항 제2호의 경우에는 제3자로부터 손해의 배상을 받을 수 있었던 금액
3. 제1항 제3호의 경우에는 소송비용(중재 또는 조정에 관한 비용 포함) 및 변호사비용과
회사의 동의를 받지 않은 행위에 의하여 증가된 손해', 'KB손해보험', '아파트종합보험', '동산', '지진위험 특별약관', NULL, '제6조', '손해방지의무', 575, 230, 'high', NULL),
    ('KB손해보험_아파트종합보험_05_제7조', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제7조 손해배상청구에 대한 회사의 해결', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제7조 손해배상청구에 대한 회사의 해결
① 피보험자가 피해자에게 손해배상책임을 지는 사고가 생긴 때에는 피해자는 이 약관에 의하
여 회사가 피보험자에게 지급책임을 지는 금액한도 내에서 회사에 대하여 보험금의 지급을
직접 청구할 수 있습니다. 그러나 회사는 피보험자가 그 사고에 관하여 가지는 항변으로써
피해자에게 대항할 수 있습니다.
【설명】
회사는 피보험자가 손해배상액의 전부 또는 일부를 피해자에게 지급하지 않아도 되는 사유
가 있는 경우에는 그에 해당하는 보험금의 지급을 거절할 수 있습니다.
② 회사가 위 제1항의 청구를 받았을 때에는 정당한 이유없이 지연되지 않도록 피보험자에게
통지하여야 하며, 회사의 요구가 있으면 계약자 및 피보험자는 필요한 서류증거의 제출, 증
언 또는 증인출석에 협조하여야 합니다.
③ 피보험자가 피해자로부터 손해배상의 청구를 받았을 경우에 회사가 필요하다고 인정할 때
에는 피보험자를 대신하여 회사의 비용으로 이를 해결할 수 있습니다. 이 경우에 회사의 요
구가 있으면 계약자 또는 피보험자는 이에 협력하여야 합니다.
④ 계약자 및 피보험자가 정당한 이유없이 제2항, 제3항의 요구에 협조하지 않은 때에는 회사
는 그로 인하여 늘어난 손해는 보상하여 드리지 않습니다.', 'KB손해보험', '아파트종합보험', '동산', '지진위험 특별약관', NULL, '제7조', '손해배상청구에 대한 회사의 해결', 648, 259, 'high', NULL),
    ('KB손해보험_아파트종합보험_05_제8조제9조', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제8조~제9조 보험금의 비례배분', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제8조~제9조 보험금의 비례배분
피보험자가 둘 이상인 때에는 회사가 지급할 보험금을 한도로 하여 재해를 입은 특수건물의
소유지분비율에 따라 보상하여 드립니다.

제9조 준용규정
이 특별약관에 정하지 않은 사항은 보통약관을 따릅니다.
