    ('KB손해보험_아파트종합보험_05_제1조제2조제3조', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제1조~제2조~제3조 보상하는 손해', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제1조~제2조~제3조 보상하는 손해
회사는 보통약관 제3조(보상하는 손해)의 손해 외에 보험의 목적에 폭발, 폭풍, 우박, 항공기,
차량 및 연기로 생긴 손해를 보상하여 드립니다.

제2조 폭발에만 적용되는 조항
회사는 보통약관 제4조(보상하지 않는 손해) 제4호의 규정에 관계없이 보험의 목적이 있는 구
내에서 생긴 폭발, 파열로 보험의 목적에 생긴 손해를 보상하여 드립니다. 그러나 기관, 기기,
증기기관, 내연기관, 수도관, 수관, 유압기 등의 물리적인 폭발, 파열이나 기계의 운동부분 또
는 회전부분이 분해되어 날아 흩어짐으로 인해 생긴 손해는 보상하여 드리지 않습니다.

제3조 폭풍과 우박에만 적용되는 조항
① 제1조(보상하는 손해)의 폭풍으로 생긴 손해라 함은 거센바람, 회오리바람 및 이와 유사한
바람으로 인한 손해를 말합니다. 태풍, 폭풍우 및 이와 유사한 비를 수반하는 기상상태로
생긴 손해에 있어서는 바람으로 인한 손해부분만을 말합니다.
② 회사는 아래와 같은 손해는 보상하여 드리지 않습니다.
1. 한기, 서리, 얼음, 눈보라, 진눈깨비, 파도, 범람, 홍수, 폭우로 생긴 손해
2. 원인의 직접, 간접에 관계없이 비, 눈 또는 모래로 인한 손해. 그러나 보험의 목적 또는
보험의 목적을 수용하고 있는 건물이 바람 또는 우박으로 직접 파손되어 그 손상 부분을
통하여 들어온 비, 눈, 모래 또는 먼지로 인하여 생긴 손해는 보상하여 드립니다.
3. 원인의 직접, 간접에 관계없이 상하수관, 배수관 또는 이와 유사한 수관으로부터 나오는
물로 인하여 보험의 목적에 생긴 손해
4. 바람 또는 우박의 직접, 간접에 관계없이 보험의 목적인 전기기구 및 장치에 전기적 사
