    ('KB손해보험_아파트종합보험_05_제1조제6조제7조제8조', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제1조~제6조~제7조~제8조 보상하는 손해', '[KB손해보험 / 아파트종합보험 / 지진위험 특별약관] 제1조~제6조~제7조~제8조 보상하는 손해
