이며 불완전한 조작에 의한 발생한 연기만을 말합니다.

제6조 소요 및 노동쟁의에만 적용되는 조항
① 제1조(보상하는 손해)의 소요라 함은 보통약관 제4조(보상하지 않는 손해) 제6호에 정한 폭
동 및 이와 비슷한 사변에 이르지 못하는 정치적 또는 사회적 소요를 말합니다.
② 회사는 아래와 같은 손해는 보상하여 드리지 않습니다.
1. 피보험자가 노동쟁의의 당사자인 경우 계약자 또는 피보험자측에 속하는 자가 노동쟁의
에 관하여 행한 행위로 보험의 목적에 생긴 손해
2. 소요 또는 노동쟁의에 대하여 공공기관이 보험의 목적을 압수, 징발 또는 파괴명령을 내
림으로써 보험의 목적에 생긴 손해

제7조 용어의 대체
보통약관에서 정한 화재는 폭발, 폭풍, 우박, 항공기, 차량, 연기, 소요 및 노동쟁의로 바꿉니
다.

