2. 인공적으로 조성된 대지의 침하나 지각변동으로 인한 손해
3. 설계결함, 시공결함, 결함재료의 사용으로 인한 손해
4. 화재, 폭발, 지진 또는 탱크나 파이프로부터의 물의 유출로 인한 손해
