6. 상점, 영업소, 창고 또는 작업장 안에 있는 상품, 원료 또는 영업소용 집기 등을 보험의
목적으로 한 때에 고객이나 그 밖의 사람에 의한 좀도둑이나 외부 침입의 흔적이 없이
생긴 분실 또는 망실의 손해
