제4조 손해보상의 한도
회사가 보상할 손해액은 보험가입금액의 범위 안에서 손해가 생긴 보험의 목적의 실제가액을
한도로 합니다. 그러나 다른 계약이 있을 때에는 보통약관 제9조(지급보험금의 계산)의 규정을
적용합니다.

