회사는 아래 사유로 생긴 손해에 대한 치료비는 보상하여 드리지 않습니다.
1. 계약자, 피보험자 또는 이들의 법정대리인의 고의
2. 타인의 자해, 자살, 자살미수, 형법상 범죄행위 또는 폭력행위(다만, 형법상 정당방위, 형
법상 긴급피난 및 정당행위로 인정되는 경우에는 보상하여 드립니다)
3. 타인의 뇌질환, 질병 또는 심신상실
4. 타인의 의수, 의족, 의안, 의치 등 신체 보조장구에 입은 손해
5. 전쟁, 혁명, 내란, 사변, 테러, 폭동, 소요, 노동쟁의 기타 이들과 유사한 사태로 생긴 손
해
6. 지진, 분화, 홍수, 해일 등의 천재지변으로 생긴 손해
7. 원인의 직접, 간접을 묻지 않고 방사선, 방사능, 원자핵 물질에 의한 손해 및 공해물질로
인한 손해
8. 타인의 신체장해에 대하여 피보험자에게 법률상의 배상책임이 있는 치료비
9. 상해를 입은 타인에 대하여 계약자 또는 피보험자(체육지도자 등 피보험자의 근로자를
포함합니다)가 치료하여 가중된 손해
10. 어린이놀이시설 구내에서 사용, 소비되는 음식물이나 재물이 피보험자의 점유를 벗어난
상태에서 그 음식물이나 재물로 인해 발생한 손해
11. 피보험자가 소유, 점유, 임차, 사용 또는 관리하는 자동차, 항공기, 선박으로 생긴 손해.
그러나 아래의 손해는 보상하여 드립니다.
가. 피보험자의 시설 내에서 피보험자가 소유, 임차 또는 사용하지 않는 자동차의 주차로
생긴 신체장해에 대한 치료비
나. 피보험자의 시설에 양륙되어 있는 선박으로 생긴 신체장해에 대한 치료비
12. 피보험자와 타인간에 치료비에 관한 약정이 있는 경우 그 약정에 의하여 가중된 치료비
13. 핵연료물질 또는 핵연료 물질에 의하여 오염된 물질의 방사성, 폭발성 그 밖의 유해한
특성 또는 이들의 특성에 의한 신체장해에 대한 치료비
14. 위 제13호 이외의 방사선을 쬐는 것 또는 방사능 오염으로 인한 신체장해에 대한 치료비
15. 티끌, 먼지, 석면, 분진 또는 소음으로 생긴 신체장해에 대한 치료비
16. 전자파, 전자장(EMF)으로 생긴 신체장해에 대한 치료비
【핵연료물질】
