제5조 보험금의 청구
피보험자가 보험금을 청구할 때에는 다음의 서류를 회사에 제출하여야 합니다.
1. 보험금 청구서(회사양식)
2. 신분증(주민등록증이나 운전면허증 등 사진이 붙은 정부기관발행 신분증, 본인이 아닌 경
우에는 본인의 인감증명서, 본인서명사실확인서 또는 안전성과 신뢰성이 확보된 전자적
