가족의 고의로 인하여 발생한 경우에는 그러하지 않습니다.', 'KB손해보험', '아파트종합보험', '동산', '실화(대물)배상책임 특별약관', NULL, '제12조', '대위권', 746, 298, 'high', NULL),
