보험의 목적의 양도는 회사의 서면동의 없이는 회사에 대하여 효력이 없으며, 회사가 서면 동
의한 경우 계약으로 인하여 생긴 권리와 의무를 함께 양도한 것으로 합니다. 다만, 의무보험인
경우에는 회사의 서면동의가 없는 경우에도 청약서에 기재된 사업을 양도하였을 때 계약으로
인하여 생긴 권리와 의무를 함께 양도한 것으로 봅니다.

제14조 조사
① 회사는 보험 목적에 대한 위험상태를 조사하기 위하여 보험기간 중 언제든지 피보험자의
시설과 업무내용을 조사할 수 있고 필요한 경우에는 그의 개선을 피보험자에게 요구할 수
있습니다.
② 회사는 제1항에 따른 개선이 완료될 때까지 계약의 효력을 정지할 수 있습니다.
③ 회사는 이 계약의 중요사항과 관련된 범위 내에서는 보험기간 중 또는 회사에서 정한 보험
금 청구서류를 접수한 날로부터 1년 이내에는 언제든지 피보험자의 회계장부를 열람할 수
있습니다.

제15조 준용규정
이 특별약관에 정하지 않은 사항은 보통약관을 따릅니다.', 'KB손해보험', '아파트종합보험', '동산', '실화(대물)배상책임 특별약관', NULL, '제13조~제14조~제15조', '양도', 542, 216, 'high', NULL),
