해에 대한 위험을 보장하기 위하여 체결됩니다.

제2조 용어의 정의
이 특별약관에서 사용되는 용어의 정의는 이 특별약관의 다른 조항에서 달리 정의되지 않는
한 다음과 같습니다.
1. 특별약관 관련 용어
가. 피보험자 : 보험사고로 인하여 타인에 대한 법률상 손해배상책임을 부담하는 손해를
입은 사람(법인인 경우에는 그 이사 또는 법인의 업무를 집행하는 그 밖의 기관)을 말
합니다.
나. 특수건물 : 특수건물이라 함은 화재로 인한 재해보상과 보험가입에 관한 법률(이하
「법」이라 합니다) 제2조 제3호와 동법시행령(이하「시행령」이라 합니다) 제2조 제1
항에서 정하는 건물을 말합니다.
다. 건물소유자손해배상책임이라 함은 법 제4조 에서 정하는 배상책임을 말합니다.
라. 타인 : 타인이라 함은 특수건물의 소유자 및 그 주거를 같이하는 직계가족(법인인 경
우에는 이사 또는 업무집행기관) 이외의 사람을 말합니다.
【직계가족】
''직계가족''은 배우자, 직계혈족, 직계혈족의 배우자, 배우자의 직계혈족''을 말합니다.
2. 보상 관련 용어
가. 배상책임: 보험증권상의 보장지역 내에서 보험기간 중에 발생된 보험사고로 인하여 타
인에게 입힌 손해에 대한 법률상의 책임을 말합니다.
나. 보상한도액: 회사와 계약자간에 약정한 금액으로 피보험자가 법률상의 배상책임을 부
담함으로써 입은 손해 중 제7조(보험금 등의 지급한도)에 따라 회사가 책임지는 금액
의 최대한도를 말합니다.', 'KB손해보험', '아파트종합보험', '동산', '교차배상책임 추가특별약관', NULL, '제1조~제2조', '목적', 803, 321, 'high', NULL),
    ('KB손해보험_아파트종합보험_21_제3조', '[KB손해보험 / 아파트종합보험 / 교차배상책임 추가특별약관] 제3조 보상하는 손해', '[KB손해보험 / 아파트종합보험 / 교차배상책임 추가특별약관] 제3조 보상하는 손해
회사는 보험에 가입한 특수건물 물건(이하 “보험의 목적”이라 합니다)의 화재로 인하여 타
인의 재물을 망그러뜨려(이하 “재물손해”라 합니다) 건물소유자 배상책임을 부담함으로써
입은 아래의 손해를 이 약관에 따라 보상하여 드립니다.
1. 피보험자가 피해자에게 지급할 책임을 지는 법률상의 손해배상금(피보험자의 과실여부를
불문합니다)
2. 계약자 또는 피보험자가 지출한 아래의 비용
가. 피보험자가 제11조(손해방지의무) 제1항 제1호의 방법을 통해 손해의 방지 또는 경감
을 위하여 지출한 필요 또는 유익하였던 비용.
나. 피보험자가 제11조(손해방지의무) 제1항 제2호에 따라 제3자로부터 손해의 배상을 받
을 수 있는 그 권리를 지키거나 행사하기 위하여 지출한 필요 또는 유익하였던 비용
【설명】
제3자로부터 손해의 배상을 받을 수 있는 경우에 피보험자가 손해배상청구를 위해 내용증
명, 재산조사, 강제집행 등을 수행하고자 지출한 각종 비용을 의미합니다.
다. 피보험자가 지급한 소송비용, 변호사비용, 중재, 화해 또는 조정에 관한 비용
라. 보험증권상 보상한도액내의 금액에 대한 공탁보증보험료. 그러나 회사는 그러한 보증
