에 따르기 위하여 지출한 비용', 'KB손해보험', '아파트종합보험', '동산', '교차배상책임 추가특별약관', NULL, '제3조', '보상하는 손해', 709, 283, 'high', NULL),
    ('KB손해보험_아파트종합보험_21_제4조', '[KB손해보험 / 아파트종합보험 / 교차배상책임 추가특별약관] 제4조 보상하지 않는 손해', '[KB손해보험 / 아파트종합보험 / 교차배상책임 추가특별약관] 제4조 보상하지 않는 손해
회사는 아래와 같은 손해는 보상하여 드리지 않습니다.
