반사실과 보험사고간 인과관계가 있는 경우에 한합니다)으로 생긴 화재, 폭발 또는 파열
로 피해자 본인이 입은 손해
2. 전쟁, 혁명, 내란, 사변, 테러, 폭동, 소요, 노동쟁의 기타 이들과 유사한 사태로 생긴
손해에 대한 배상책임
3. 지진, 분화, 홍수, 해일 등의 천재지변으로 생긴 손해에 대한 배상책임
4. 핵연료물질 또는 핵연료 물질에 의하여 오염된 물질의 방사성, 폭발성 그 밖의 유해한
특성 또는 이들의 특성에 의한 사고로 생긴 손해에 대한 배상책임
5. 위 제4호 이외의 방사선을 쬐는 것 또는 방사능 오염으로 인한 손해
6. 피보험자와 타인 간에 손해배상에 관한 약정이 있는 경우 그 약정에 의하여 가중된 손해
배상책임. 그러나 약정이 없었더라도 법률규정에 의하여 피보험자가 부담하게 될 배상책
임은 보상합니다.
7. 피보험자가 소유, 점유, 임차, 사용하거나 보호, 관리, 통제(원인에 관계없이 모든 형태
의 실질적인 통제행위를 포함합니다)하는 재물이 손해를 입음으로써 그 재물에 대하여
정당한 권리를 가지는 사람에 대한 손해배상책임
8. 벌과금 및 징벌적 손해에 대한 배상책임
9. 티끌, 먼지, 석면, 분진 또는 소음으로 생긴 손해에 대한 배상책임
10. 전자파, 전자장(EMF)으로 생긴 손해에 대한 배상책임
