② 회사가 제1항에 의하여 보상을 한 경우에는 보상한도액에서 그 보상액을 뺀 잔액을 나머지
보험기간에 대한 보상한도액으로 합니다.

제8조 의무보험과의 관계
① 회사는 이 약관에 의하여 보상하여야 하는 금액이 의무보험에서 보상하는 금액을 초과할
때에 한하여 그 초과액만을 보상합니다. 다만, 이 계약이 의무보험인 경우에는 그러하지
않으며, 의무보험이 다수인 경우에는 제9조(보험금의 분담)를 따릅니다.
② 제1항의 의무보험은 피보험자가 법률에 의하여 의무적으로 가입하여야 하는 보험으로서 공
제계약을 포함합니다.
③ 피보험자가 의무보험에 가입하여야 함에도 불구하고 가입하지 않은 경우에는 그가 가입했
