제11조 손해방지의무
① 보험사고가 생긴 때에는 계약자 또는 피보험자는 아래의 사항을 이행하여야 합니다.
1. 손해의 방지 또는 경감을 위하여 노력하는 일(피해자에 대한 응급처치, 긴급호송 또는
그 밖의 긴급조치를 포함합니다)
2. 제3자로부터 손해의 배상을 받을 수 있는 경우에는 그 권리를 지키거나 행사하기 위한
필요한 조치를 취하는 일
3. 손해배상책임의 전부 또는 일부에 관하여 지급(변제), 승인 또는 화해를 하거나 소송,
중재 또는 조정을 제기하거나 신청하고자 할 경우에는 미리 회사의 동의를 받는 일
② 계약자 또는 피보험자가 정당한 이유 없이 제1항의 의무를 이행하지 않았을 때에는 제3조
(보상하는 손해)에 의한 손해에서 다음의 금액을 뺍니다.
1. 제1항 제1호의 경우에는 그 노력을 하였더라면 손해를 방지 또는 경감할 수 있었던 금액
2. 제1항 제2호의 경우에는 제3자로부터 손해의 배상을 받을 수 있었던 금액
3. 제1항 제3호의 경우에는 소송비용(중재 또는 조정에 관한 비용 포함) 및 변호사비용과
