가 있는 경우에는 그에 해당하는 보험금의 지급을 거절할 수 있습니다.
② 회사가 위 제1항의 청구를 받았을 때에는 지체 없이 피보험자에게 통지하여야 하며, 회사
의 요구가 있으면 계약자 및 피보험자는 필요한 서류증거의 제출, 증언 또는 증인출석에
협조하여야 합니다.
③ 피보험자가 피해자로부터 손해배상의 청구를 받았을 경우에 회사가 필요하다고 인정할 때
에는 피보험자를 대신하여 회사의 비용으로 이를 해결할 수 있습니다. 이 경우에 회사의
요구가 있으면 계약자 또는 피보험자는 이에 협력하여야 합니다.
④ 계약자 및 피보험자가 정당한 이유 없이 제2항, 제3항의 요구에 협조하지 않은 때에는 회
