② 회사는 피보험자에 대하여 보상책임을 지는 한도 내에서 제1항의 절차에 협조하거나 대행
합니다.
【보상책임을 지는 한도】
동일한 사고로 이미 지급한 보험금이나 가지급보험금이 있는 경우에는 그 금액을 공제한
액수를 말합니다.
③ 회사가 제1항의 절차에 협조하거나 대행하는 경우에는 피보험자는 회사의 요청에 따라 협
력해야 하며, 피보험자가 정당한 이유없이 협력하지 않을 경우에는 그로 말미암아 늘어난
손해에 대해서 보상하지 않습니다.
④ 회사는 다음의 경우에는 제1항의 절차를 대행하지 않습니다.
1. 피보험자가 피해자에 대하여 부담하는 법률상의 손해배상책임액이 보험증권에 기재된 보
상한도액을 명백하게 초과하는 때
2. 피보험자가 정당한 이유 없이 협력하지 않을 때
⑤ 회사가 제1항의 절차를 대행하는 경우에는, 피보험자에 대하여 보상책임을 지는 한도 내에
서, 가압류나 가집행을 면하기 위한 공탁금을 피보험자에게 대부할 수 있으며 이에 소요되
는 비용을 보상합니다. 이 경우 대부금의 이자는 공탁금에 붙여지는 것과 같은 이율로 하
며, 피보험자는 공탁금(이자를 포함합니다)의 회수청구권을 회사에 양도하여야 합니다.', 'KB손해보험', '아파트종합보험', '동산', '교차배상책임 추가특별약관', NULL, '제13조', '합의․절충․중재․소송의 협조․대행 등', 749, 299, 'high', NULL),
