【가지급보험금】
보험금이 지급기한 내에 지급되지 못할 것으로 판단되는 경우 회사가 예상되는 보험금의
일부를 먼저 지급하는 제도로 피보험자가 필요로 하는 비용을 보전해 주기 위해 회사가
먼저 지급하는 임시 교부금을 말합니다.
② 회사가 제1항의 규정에 정한 지급기일 내에 보험금을 지급하지 않았을 때에는 그 다음날부
터 지급일까지의 기간에 대하여 <부표> ‘보험금을 지급할 때의 적립이율’에 따라 연단위
복리로 계산한 금액을 보험금에 더하여 지급합니다. 그러나 계약자 또는 피보험자의 책임
있는 사유로 지급이 지연될 때에는 그 해당기간에 대한 이자를 더하여 지급하지 않습니다.
<부표> 보험금을 지급할 때의 적립이율
기 간 지 급 이 자
지급기일의 다음 날부터 30일 이내 기간 보험계약대출이율
지급기일의 31일이후부터 60일이내 기간 보험계약대출이율+ 가산이율(4.0%)
지급기일의 61일이후부터 90일이내 기간 보험계약대출이율+ 가산이율(6.0%)
지급기일의 91일이후 기간 보험계약대출이율+ 가산이율(8.0%)
주) 보험계약대출이율은 보험개발원이 공시하는 보험계약대출이율을 적용합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제2관 보험금의 지급', '제7조', '보험금의 지급절차', 793, 317, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제8조', '[KB손해보험 / 주택종합보험 / 제2관 보험금의 지급] 제8조 보험금 등의 지급한도', '[KB손해보험 / 주택종합보험 / 제2관 보험금의 지급] 제8조 보험금 등의 지급한도
① 제3조(보상하는 손해) 제1항의 손해에 의한 보험금과 제3조(보상하는 손해) 제2항의 잔존물
제거비용은 각각 제9조(지급보험금의 계산)를 준용하여 계산하며, 그 합계액은 보험증권에
기재된 보험가입금액을 한도로 합니다. 다만, 잔존물 제거비용은 손해액의 10%를 초과할
수 없습니다.
② 제3조(보상하는 손해) 제2항의 비용손해 중 손해방지비용, 대위권 보전비용 및 잔존물 보전
비용은 제9조(지급보험금의 계산)를 준용하여 계산한 금액이 보험가입금액을 초과하는 경우
에도 이를 지급합니다.
【예시】
보험가액 5,000만원 / 보험가입금액 5,000만원 인 경우,
보험목적물 손해액 4,700만원, 손해방지비용 200만원 / 대위권 보전비용 300만원 발생
→ 전체 지급보험금 = 5,200만원
③ 제3조(보상하는 손해) 제2항의 비용손해 중 기타 협력비용은 보험가입금액을 초과한 경우에
도 이를 전액 지급합니다.
④ 제1항 내지 제3항에도 불구하고 아래 각 호의 손해에 의한 보험금은 보험증권에 별도로 정
한 보험가입금액을 한도로 합니다.
1. 급배수설비 누출로 생긴 손해
2. 건물에 부착된 유리의 손해(유리의 부착비용 포함)
⑤ 회사가 손해를 보상한 경우에는 그 지급액(건물 및 가재의 지급액의 합계)이 한 번의 사고
에 대하여 보험가입금액(보험가액을 한도로 하며, 건물 및 가재의 보험가입금액 합계를 기
준으로 계산)미만인 때에는 이 계약의 보험가입금액은 감액되지 않으며, 이상인 때에는 그
손해보상의 원인이 생긴 때부터 계약은 소멸됩니다.
⑥ 제5항에도 불구하고, 제4항에서 정한 손해를 보상한 경우에는 제5항을 적용하지 않습니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제2관 보험금의 지급', '제8조', '보험금 등의 지급한도', 854, 341, 'high', NULL),
