2. 가재는 시가(재조달가액에서 감가상각이 반영된 금액)를 기준으로 계산한 손해액을 가재
의 보험가입금액 내에서 보상합니다.
3. 급배수설비 누출 손해는 제8조(보험금 등의 지급한도)제4항에서 정한 별도의 보험가입금
액 내에서 보상합니다. 단 건물은 재조달가액 기준, 가재는 시가를 기준으로 하여 손해액
을 계산합니다.
4. 건물에 부착된 유리의 손해(유리의 부착비용을 포함)는 제8조(보험금 등의 지급한도)에서
