1. 다른 계약이 이 계약과 지급보험금의 계산방법이 같은 경우 :
계약A: 보험가입금액 2,000만원 / 계약B: 보험가입금액 3,000만원 / 보험가액 : 2,000
만원 / 손해액 : 1,000만원
→ 계약A보험회사 : 400만원 지급 = 1,000만원 × 2,000만원 / (2,000만원 + 3,000만원)
→ 계약B보험회사 : 600만원 지급 = 1,000만원 × 3,000만원 / (2,000만원 + 3,000만원)
2. 다른 계약이 이 계약과 지급보험금의 계산방법이 다른 경우 :
계약A: 책임액 1,000만원 / 계약B: 책임액 1,000만원 / 손해액 : 1,000만원
→ 계약A보험회사 : 500만원 지급 = 1,000만원 × 1,000만원 / (1,000만원 + 1,000만원)
→ 계약B보험회사 : 500만원 지급 = 1,000만원 × 1,000만원 / (1,000만원 + 1,000만원)
3. 이 보험계약이 타인을 위한 보험계약이면서 보험계약자가 다른 계약으로 인하여 상법 제
682조에 따른 대위권 행사의 대상이 된 경우에는 실제 그 다른 계약이 존재함에도 불구
하고 그 다른 계약이 없다는 가정 하에 제1항에 따라 계산한 보험금을 그 다른 보험계약
에 우선하여 이 보험계약에서 지급합니다.
4. 이 보험계약을 체결한 보험회사가 타인을 위한 보험에 해당하는 다른 계약의 보험계약자
에게 상법 제682조에 따른 대위권을 행사할 수 있는 경우에는 이 보험계약이 없다는 가
정 하에 다른 계약에서 지급받을 수 있는 보험금을 초과한 손해액을 이 보험계약에서 보
상합니다.
③ 하나의 보험가입금액으로 둘 이상의 보험의 목적을 계약하는 경우에는 전체가액에 대한 각
가액의 비율로 보험가입금액을 비례배분하여 제1항 또는 제2항의 규정에 따라 지급보험금
을 계산합니다.
