계약자, 피보험자 또는 이들의 대리인은 청약할 때 청약서(질문서를 포함합니다)에서 질문한
사항에 대하여 알고 있는 사실을 반드시 사실대로 알려야 합니다.

제16조 계약 후 알릴 의무
① 계약을 맺은 후 보험의 목적에 아래와 같은 사실이 생긴 경우에는 계약자나 피보험자는 지
체없이 서면으로 회사에 알리고 보험증권에 확인을 받아야 합니다.
1. 이 계약에서 보장하는 위험과 동일한 위험을 보장하는 계약을 다른 보험자와 체결하고자
할 때 또는 이와 같은 계약이 있음을 알았을 때
2. 양도할 때
3. 보험의 목적 또는 보험의 목적을 수용하는 건물의 구조를 변경, 개축, 증축하거나 계속하
여 15일 이상 수선할 때
4. 보험의 목적 또는 보험의 목적을 수용하는 건물의 용도를 변경함으로써 위험이 변경되는
경우
5. 보험의 목적 또는 보험의 목적이 들어있는 건물을 계속하여 30일 이상 비워 두거나 휴업
하는 경우
6. 다른 곳으로 옮길 때
7. 청약서의 기재사항을 변경하고자 할 때 또는 변경이 생겼음을 알았을 때
8. 위험이 뚜렷이 변경되거나 변경되었음을 알았을 때
② 회사는 제1항에 따라 위험이 감소된 경우에는 그 차액보험료를 돌려드리며, 위험이 증가된
경우에는 통지를 받은 날부터 1개월 이내에 보험료의 증액을 청구하거나 계약을 해지할 수
있습니다.
③ 계약자 또는 피보험자는 주소 또는 연락처가 변경된 경우에는 지체없이 이를 회사에 알려
야 합니다. 다만, 계약자 또는 피보험자가 알리지 않은 경우 회사가 알고 있는 최종의 주소
또는 연락처로 등기우편 등 우편물에 대한 기록이 남는 방법으로 회사가 알린 사항은 일반
적으로 도달에 필요한 기간이 지난 때에는 계약자 또는 피보험자에게 도달한 것으로 봅니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제3관 계약자의 계약 전 알릴 의무 등', '제15조~제16조', '계약 전 알릴 의무', 909, 363, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제17조제18조제19조', '[KB손해보험 / 주택종합보험 / 제3관 계약자의 계약 전 알릴 의무 등] 제17조~제18조~제19조 사기에 의한 계약', '[KB손해보험 / 주택종합보험 / 제3관 계약자의 계약 전 알릴 의무 등] 제17조~제18조~제19조 사기에 의한 계약
계약자, 피보험자 또는 이들의 대리인의 사기에 의하여 계약이 성립되었음을 회사가 증명하는
경우에는 계약일부터 5년 이내(사기사실을 안 날부터 1개월 이내)에 계약을 취소할 수 있습니
다.

제18조 보험계약의 성립
① 계약은 계약자의 청약과 회사의 승낙으로 이루어집니다.
② 회사는 계약의 청약을 받고 보험료 전액 또는 제1회 보험료(이하 ‘제1회 보험료 등’이라 합
니다)를 받은 경우에는 청약일부터 30일 이내에 승낙 또는 거절의 통지를 하며 통지가 없
으면 승낙한 것으로 봅니다.
③ 회사가 청약을 승낙한 때에는 지체 없이 보험증권을 계약자에게 교부하여 드리며, 청약을
거절한 경우에는 거절통지와 함께 받은 금액을 계약자에게 돌려드립니다.
④ 이미 성립한 계약을 연장하거나 변경하는 경우에는 회사는 보험증권에 그 사실을 기재함으
로써 보험증권의 교부에 대신할 수 있습니다.

제19조 청약의 철회
① 계약자는 보험증권을 받은 날부터 15일 이내에 그 청약을 철회할 수 있습니다. 다만, 의무
보험의 경우에는 철회의사를 표시한 시점에 동종의 다른 의무보험에 가입된 경우에만 철회
할 수 있으며, 보험기간이 90일 이내인 계약 또는 전문금융소비자가 체결한 계약은 청약을
철회할 수 없습니다.
【전문금융소비자】
보험계약에 관한 전문성, 자산규모 등에 비추어 보험계약에 따른 위험감수능력이 있는 자
로서, 국가, 지방자치단체, 한국은행, 금융회사, 주권상장법인 등을 포함하며 「금융소비자
보호에 관한 법률」제2조(정의) 제9호에서 정하는 전문금융소비자를 말합니다.
【일반금융소비자】
전문금융소비자가 아닌 계약자를 말합니다.
② 제1항에도 불구하고 청약한 날부터 30일(단, 만 65세 이상의 계약자가 통신수단 중 전화를
이용하여 체결한 경우 45일)이 초과된 계약은 청약을 철회할 수 없습니다.
③ 청약철회는 계약자가 전화로 신청하거나, 철회의사를 표시하기 위한 서면, 전자우편, 휴대
전화 문자메시지 또는 이에 준하는 전자적 의사표시(이하 ‘서면 등’이라 합니다)를 발송한
때 효력이 발생합니다. 계약자는 서면 등을 발송한 때에 그 발송 사실을 회사에 지체없이
알려야 합니다.
④ 계약자가 청약을 철회한 때에는 회사는 청약의 철회를 접수한 날부터 3영업일 이내에 납입
한 보험료를 계약자에게 돌려드리며, 보험료 반환이 늦어진 기간에 대하여는 ‘보험개발원이
공시하는 보험계약대출이율’을 연단위 복리로 계산한 금액을 더하여 지급합니다. 다만, 계
약자가 제1회 보험료 등을 신용카드로 납입한 계약의 청약을 철회하는 경우에 회사는 청약
의 철회를 접수한 날부터 3영업일 이내에 해당 신용카드회사로 하여금 대금청구를 하지 않
도록 해야 하며, 이 경우 회사는 보험료를 반환한 것으로 봅니다.
⑤ 청약을 철회할 때에 이미 보험금 지급사유가 발생하였으나 계약자가 그 보험금 지급사유가
발생한 사실을 알지 못한 경우에는 청약철회의 효력은 발생하지 않습니다.
⑥ 제1항에서 보험증권을 받은 날에 대한 다툼이 발생한 경우 회사가 이를 증명하여야 합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제3관 계약자의 계약 전 알릴 의무 등', '제17조~제18조~제19조', '사기에 의한 계약', 1543, 617, 'high', NULL),
