에 따른 보험료를 계약자에게 지급합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제5관 보험료의 납입', '제33조', '보험료의 환급', 67, 26, 'high', NULL),
