① 제27조(보험료의 납입이 연체되는 경우 납입최고[독촉]와 계약의 해지)에 따라 계약이 해지
되었으나 계약자가 제33조(보험료의 환급)에 따라 보험료를 돌려받지 않은 경우 계약자는
해지된 날부터 3년 이내에 회사가 정한 절차에 따라 계약의 부활(효력회복)을 청약할 수 있
습니다. 이 경우 회사가 그 청약을 승낙한 때에는 계약자는 부활(효력회복)을 청약한 날까
지의 연체된 보험료에 보험개발원이 공시하는 월평균 정기예금이율 + 1% 범위내에서 각
상품별로 회사가 정하는 이율로 계산한 금액을 더하여 납입하여야 합니다.
② 제1항에 따라 해지계약을 부활(효력회복)하는 경우에는 제15조(계약 전 알릴 의무), 제17조
