① 타인을 위한 계약의 경우 제33조(보험료의 환급)에 따른 계약자의 환급금 청구권에 대한 강
제집행, 담보권실행, 국세 및 지방세 체납처분절차에 의해 계약이 해지된 경우에는, 회사는
해지 당시의 피보험자가 계약자의 동의를 얻어 계약 해지로 회사가 채권자에게 지급한 금
액을 회사에게 지급하고 제22조(계약내용의 변경 등) 제1항의 절차에 따라 계약자 명의를
피보험자로 변경하여 계약의 특별부활(효력회복)을 청약할 수 있음을 피보험자에게 통지하
여야 합니다.
② 회사는 제1항에 의한 계약자 명의변경 신청 및 계약의 특별부활(효력회복) 청약을 승낙하
며, 계약은 청약한 때부터 특별부활(효력회복) 됩니다.
③ 회사는 제1항의 통지를 계약이 해지된 날부터 7일 이내에 하여야 합니다. 다만, 회사의 통
지가 7일을 지나서 도달하고 이후 피보험자가 제1항에 의한 계약자 명의변경 신청 및 계약
의 특별부활(효력회복)을 청약한 경우에는 계약이 해지된 날부터 7일이 되는 날에 특별부활
