해석하지 않습니다.
【신의성실의 원칙】
권리의 행사와 의무의 이행은 신의와 성실을 가지고 행동하여 상대방의 신뢰와 기대를 배
반하여서는 안 된다는 원칙(「민법」제2조 제1항)
② 회사는 약관의 뜻이 명백하지 않은 경우에는 계약자에게 유리하게 해석합니다.
③ 회사는 보상하지 않는 손해 등 계약자나 피보험자에게 불리하거나 부담을 주는 내용은 확
대하여 해석하지 않습니다.

제38조 설명서 교부 및 보험안내자료 등의 효력
① 회사는 일반금융소비자에게 청약을 권유하거나 일반금융소비자가 설명을 요청하는 경우 보
험상품에 관한 중요한 사항을 계약자가 이해할 수 있도록 설명하고 계약자가 이해하였음을
서명(「전자서명법」 제2조 제2호에 따른 전자서명을 포함), 기명날인 또는 녹취 등을 통해
확인받아야 하며, 설명서를 제공하여야 합니다.
② 설명서, 약관, 계약자 보관용 청약서 및 보험증권의 제공 사실에 관하여 계약자와 회사간에
다툼이 있는 경우에는 회사가 이를 증명하여야 합니다.
③ 보험설계사 등이 모집과정에서 사용한 회사 제작의 보험안내자료의 내용이 약관의 내용과
다른 경우에는 계약자에게 유리한 내용으로 계약이 성립된 것으로 봅니다.
【보험안내자료】
계약의 청약을 권유하기 위해 만든 서류 등을 말합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제37조~제38조', '약관의 해석', 718, 287, 'high', NULL);

