① 회사는 계약과 관련하여 임직원, 보험설계사 및 대리점의 책임있는 사유로 인하여 계약자
및 피보험자에게 발생된 손해에 대하여 관계 법령 등에 따라 손해배상의 책임을 집니다.
② 회사는 보험금 지급 거절 및 지연지급의 사유가 없음을 알았거나 알 수 있었음에도 불구하
고 소를 제기하여 계약자 또는 피보험자에게 손해를 가한 경우에는 그에 따른 손해를 배상
할 책임을 집니다.
③ 회사가 보험금 지급여부 및 지급금액에 관하여 현저하게 공정을 잃은 합의로 계약자 또는
피보험자에게 손해를 가한 경우에도 회사는 제2항에 따라 손해를 배상할 책임을 집니다.
【설명】
현저하게 공정을 잃은 합의란 사회통념상 현저하게 타당성을 잃은 합의를 말합니다.

제40조 개인정보보호
① 회사는 이 계약과 관련된 개인정보를 이 계약의 체결, 유지, 보험금 지급 등을 위하여 「개
인정보 보호법」,「신용정보의 이용 및 보호에 관한 법률」등 관계 법령에 정한 경우를 제
외하고 계약자 또는 피보험자의 동의없이 수집, 이용, 조회 또는 제공하지 않습니다. 다만,
회사는 이 계약의 체결, 유지, 보험금 지급 등을 위하여 위 관계 법령에 따라 계약자 및 피
보험자의 동의를 받아 다른 보험회사 및 보험관련단체 등에 개인정보를 제공할 수 있습니다.
② 회사는 계약과 관련된 개인정보를 안전하게 관리하여야 합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제39조~제40조', '회사의 손해배상책임', 714, 285, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제41조제42조', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제41조~제42조 준거법', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제41조~제42조 준거법
이 계약은 대한민국 법에 따라 규율되고 해석되며, 약관에서 정하지 않은 사항은 ｢금융소비자
보호에 관한 법률｣, 상법, 민법 등 관계 법령을 따릅니다.

제42조 예금보험에 의한 지급보장
회사가 파산 등으로 인하여 보험금 등을 지급하지 못할 경우에는 예금자보호법에서 정하는 바
에 따라 그 지급을 보장합니다.
【설명】
예금자보호제도란 예금자보호법에 의해 설립된 예금보험공사가 평소에 금융회사로부터
보험료를 받아 기금을 적립한 후, 금융회사가 영업정지나 파산 등으로 예금을 지급할 수
없게 되면 금융회사를 대신하여 예금을 지급하는 제도를 말합니다.
이 보험계약은 예금자보호법에 따라 해약환급금(또는 만기 시 보험금)에 기타지급금을 합
한 금액이 1인당 “1억원까지”(본 보험회사의 여타 보호 상품과 합산) 보호됩니다. 이와
별도로 본 보험회사 보호상품의 사고보험금을 합산한 금액이 1인당 “1억원까지” 보호됩
니다. 다만, 보험계약자 및 보험료 납부자가 법인인 보험계약의 경우에는 보호되지 않습
니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제41조~제42조', '준거법', 550, 220, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제43조', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제43조 계약의 적용 범위', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제43조 계약의 적용 범위
① 피보험자가 다음 중 한가지의 단체에 소속되어야 하며, 단체를 대표하여 계약자로 된 자가
단체보험 계약상의 모든 권리, 의무를 행사할 수 있어야 합니다.
1. 제1종 단체
동일한 회사, 사업장, 관공서, 국영기업체, 조합 등 5인 이상의 근로자를 고용하고 있는 단
체. 다만, 사업장, 직제, 직종 등으로 구분되어 있는 경우의 단체소속 여부는 관련법규 등
에서 정하는 바에 따릅니다.
2. 제2종 단체
비영리법인단체 또는 변호사회, 의사회등 동업자단체로서 5인 이상의 구성원이 있는 단체
3. 제3종 단체
그밖에 단체의 구성원을 확정시킬 수 있고 계약의 일괄적인 관리가 가능한 단체로서 5인
이상의 구성원이 있는 단체
② 제1항의 대상단체에 소속된 자로서 동일한 보험계약을 체결한 5인 이상의 피보험자로 피보
험단체를 구성하여야 하며, 단체 구성원의 일부만을 대상으로 가입하는 경우에는 다음의 조
건을 모두 충족하여야 합니다.
1. 단체의 내규에 의한 복지제도로서 노사합의에 의하며, 보험료의 일부를 단체 또는 단체
의 대표자가 부담하여야 합니다.
2. 제1항 제2호 및 제3호에 해당하는 단체는 내규에 의해 단체의 대표자와 보험회사가 협정
에 의해 체결하여야 합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제43조', '계약의 적용 범위', 647, 258, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제44조제45조', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제44조~제45조 상법 제735조3의 적용', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제44조~제45조 상법 제735조3의 적용
① 제43조(계약의 적용 범위)의 단체가 피보험자를 확정할 수 있고 계약의 일괄적 관리가 가능
하며, 규약에 따라 계약을 체결하는 경우 피보험자의 서면에 의한 동의를 얻지 않아도 되
며, 계약자에게만 보험증권을 드릴 수 있습니다.
② 제1항의 규약은 보험의 종류 및 일괄 가입에 관한 사항이 포함되어야 하며, 동의 또는 협의
를 통하여 피보험자들의 의사가 규약에 반영될 수 있어야 합니다. 다만, 보험수익자를 계약
자 등 피보험자의 이해에 반하는 자로 지정하는 경우에는 해당 내용이 규약에 반영되어야
하며, 반영되지 않은 경우에는 별도 피보험자의 동의를 받아야 합니다.
③ 보험회사는 계약자를 통해 단체의 규약이 제2항을 충족하고 있는지 확인을 해야 하며, 계약
자는 이에 협조하여야 합니다.

제45조 단체요율의 적용
① 제43조(계약의 적용 범위)의 단체는 단체요율을 적용할 수 있습니다. 다만, 제3종 단체는
구성원이 명확하고 위험의 동질성이 확보되어야 합니다.
② 단체 구성원의 일부만을 대상으로 가입하는 경우에는 대상단체의 위험과 피보험단체의 위
험의 동질성이 유지되어야 합니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제44조~제45조', '상법 제735조3의 적용', 610, 244, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제46조제47조', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제46조~제47조 보험의 목적의 증가 감소 또는 교체', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제46조~제47조 보험의 목적의 증가 감소 또는 교체
① 계약을 맺은 후 보험의 목적을 증가, 감소 또는 교체코자 하는 경우에는 계약자 또는 피보
험자는 지체없이 서면으로 그 사실을 회사에 알리고 회사의 승인을 받아야 합니다.
② 이 계약기간 중 보험의 목적 감소의 경우는 당해 보험의 목적의 계약은 해지된 것으로 하
며 새로이 증가 또는 교체되는 보험의 목적의 보험기간은 이 계약의 남은 보험기간으로 하
고, 이로 인하여 발생되는 추가 또는 환급보험료는 일단위로 계산하여 받거나 돌려 드립니
다.
③ 회사는 제1항 및 제2항을 위반하였을 경우에 새로이 증가 또는 교체되는 해당 보험의 목적
에 대하여는 보상하여 드리지 않습니다.
④ 제1항에 따라 보험의 목적이 교체되는 경우에는 보험의 목적 교체 전 계약과 동일한 보장
조건 및 인수기준에 따라 가입될 수 있으며, 보험의 목적 교체시점부터 잔여 보험기간(보험
의 목적 교체 전 계약의 보험기간 만료일)까지 보상하여 드립니다.

제47조 개별계약으로의 전환
① 피보험자가 퇴직 등의 사유로 인하여 피보험단체에서 탈퇴하는 경우 피보험자가 보험료의
일부를 부담한 경우에 한하여 탈퇴일로부터 1개월 이내에 계약자 또는 피보험자는 회사의
승낙을 얻어 개별계약으로 전환할 수 있으며, 이 경우 피보험자는 개별계약의 계약자가 됩
니다.
② 제1항에 따라 개별계약으로 전환시에는 전환후 피보험자의 보험기간은 이 계약의 남은 기
간으로 하고, 이로 인하여 발생하는 추가 또는 환급되는 보험료는 보험료 및 해약환급금 산
출방법서에서 정한 바에 따라 일단위로 계산하여 받거나 돌려 드립니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제46조~제47조', '보험의 목적의 증가 감소 또는 교체', 829, 331, 'high', NULL),
    ('KB손해보험_주택종합보험_00_제48조제49조', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제48조~제49조 보험증권의 발급', '[KB손해보험 / 주택종합보험 / 제7관 분쟁의 조정 등] 제48조~제49조 보험증권의 발급
① 회사는 계약자에게 보험증권을 드려야 하고, 그 약관의 주요한 내용을 알려드립니다.
② 계약자의 요청이 있을 경우, 개별 피보험자에게는 가입증명서를 발급하여 드립니다.

제49조 적용상의 특칙
계약자가 아닌 단체의 소속원이 보험료 전부 또는 일부를 부담하는 경우에는 그 소속원이 계
약자로서의 권리를 행사할 수 있습니다.
