정산되기 이전 일지라도 새로이 증가 또는 교체 된 피보험자에 대해 생긴 손해를 보상하여
드립니다.

제2조 피보험자의 명부
계약자는 항상 피보험자의 명부를 비치하여 회사가 열람을 요구할 경우에는 이에 따라야 합니다.

제3조 예치 보험료
예치보험료는 계약 체결일 이전 1개월 동안 1일 평균인원수에 정해진 보험요율을 적용하여 계
산합니다.

제4조 보험료의 정산방법
보험료는 피보험자수의 증감을 기초로 하여 다음과 같이 정산합니다.
1. 계약자는 매월 10일까지 전월말까지의 피보험자에 관한 서류를 회사에 제출하여야 합니
다. 그러나 계약이 효력상실 또는 해지된 경우에는 효력상실 또는 해지일까지의 보험료
를 확정하기 위하여 필요한 서류를 효력상실 또는 해지 즉시 회사에 제출하여야 합니다.
2. 회사는 보험기간중이나 보험기간 만료 후 보험료를 산출하기 위하여 필요하다고 인정될
경우에는 계약자의 서류를 열람할 수 있습니다.
3. 회사는 보험기간 만료와 동시에 피보험자수에 따라 산출된 확정보험료와 계약체결 시 산
출한 예치보험료를 비교하여 그 차액을 정산합니다.
4. 동조 제1항에도 불구하고, 계약자와 협의를 통해 피보험자수에 관한 서류 제출 주기를
변경할 수 있습니다.', 'KB손해보험', '주택종합보험', '동산', 'KB주택종합보험 보통약관', '제7관 분쟁의 조정 등', '제1조~제2조~제3조~제4조', '보험료의 정산', 782, 312, 'high', NULL),
