동, 부적합 등을 확인, 수정, 시험하기 위하여 피보험자가 자신이나 타인에게 행하였거나
타인으로부터 받은 어떠한 조언, 지도, 설계의 평가, 설치의 검사, 유지관리, 수리 또는 감
독상의 오류, 부적절, 오작동으로 인하여 발생되는 손해와 결과적 손실을 보상하지 않습니
다.
