① 회사는 보통약관 제4조(보상하지 않는 손해) 제9호에도 불구하고, 보험기간 중에 보험의 목
적이 보험증권에 기재된 주택의 구내에 보관되어 있는 동안에 강도 또는 절도(그 미수를 포
함합니다)로 생긴 도난, 훼손 또는 망가진 손해를 보상하여 드립니다.
② 도난당한 보험의 목적을 도로 찾는 경우 그에 소요된 정당한 비용은 보상하여 드립니다.

제2조 보험목적의 범위
① 이 특별약관에서 보험의 목적은 보험증권에 기재된 주택 내에 있는 가재를 말합니다.
② 아래의 물건은 보험의 목적에 포함되지 않습니다.
1. 통화, 유가증권, 인지, 우표 및 이와 비슷한 것
2. 귀금속, 귀중품, 보옥, 보석, 글․그림, 골동품, 조각물 및 이와 비슷한 것
3. 원고, 설계서, 도안, 물건의 원본, 모형, 증서, 장부, 금형(쇠틀), 목형(나무틀), 소프트웨
어 및 이와 비슷한 것
4. 차량(자동2륜차 및 자동3륜차 포함), 선박, 항공기
5. 동물, 식물, 농작물 기타 이와 유사한 것
【귀중품】
무게나 부피가 휴대할 수 있으며, 점당 300만원 이상인 것, 다만 카메라, 캠코더, 휴대용컴
퓨터, 가전제품 등의 생활용품은 보험의 목적에 포함됩니다.', 'KB손해보험', '주택종합보험', '동산', '가재 도난위험 특별약관', NULL, '제1조~제2조', '보상하는 손해', 632, 252, 'high', NULL),
    ('KB손해보험_주택종합보험_02_제3조제4조', '[KB손해보험 / 주택종합보험 / 가재 도난위험 특별약관] 제3조~제4조 보상하지 않는 손해', '[KB손해보험 / 주택종합보험 / 가재 도난위험 특별약관] 제3조~제4조 보상하지 않는 손해
회사는 아래의 사유로 인한 손해는 보상하여 드리지 않습니다.
1. 계약자, 피보험자의 악의 또는 중대한 과실로 생긴 도난
2. 피보험자의 가족, 친족, 고용인, 동거인, 숙박인 또는 감수인(監守人)이 저지르거나 가담
한 도난
3. 전쟁, 폭동, 민요(民擾) 또는 그 밖의 사변으로 생긴 도난
4. 화재나 지진, 분화, 해일, 폭발, 파열 또는 그 밖의 변재가 일어났을 때에 생긴 도난
5. 보험의 목적이 건물구내 밖에 있는 동안에 생긴 도난
6. 재고를 조사할 때 발견된 손해
7. 사기 또는 횡령으로 인한 손해
8. 보험의 목적이 들어있는 건물을 계속하여 72시간 이상 비워둔 사이에 생긴 도난
9. 외부로부터의 침입이 없이 생긴 분실 도는 망실의 손해

제4조 손해의 통지 및 조사
① 보험의 목적에 손해가 생긴 경우 계약자, 피보험자, 피보험자의 가족, 감수인 또는 당직자
는 지체없이 이를 회사에 알려야 합니다.
② 계약자 또는 피보험자가 제1항의 통지를 게을리하여 손해가 증가된 때에는 회사는 그 증가
된 손해는 보상하여 드리지 않습니다.
③ 회사가 제1항에 대한 손해의 사실을 확인하기 어려운 경우에는 계약자 또는 피보험자에게
필요한 증거자료의 제출을 요청할 수 있습니다.
