제2조 보험목적의 범위
① 이 특별약관에서 보험의 목적은 아래의 물건을 말하며, 보험증권에 기재하여야 합니다.
1. 통화, 유가증권, 인지, 우표 및 이와 비슷한 것
2. 귀금속, 귀중품, 보옥, 보석, 글․그림, 골동품, 조각물 및 이와 비슷한 것
