7. 사기 또는 횡령으로 인한 손해
8. 보험의 목적이 들어있는 건물을 계속하여 72시간 이상 비워둔 사이에 생긴 도난
9. 외부로부터의 침입이 없이 생긴 분실 도는 망실의 손해

