② 동일한 계약의 목적과 동일한 사고에 관하여 보험금을 지급하는 다른 계약(공제계약을 포함
합니다)이 있고 이들의 보험가입금액의 합계액이 보험가액보다 클 경우에는 아래에 따라 지
급보험금을 계산합니다. 이 경우 보험자 1인에 대한 보험금 청구를 포기한 경우에도 다른
보험자의 지급보험금 결정에는 영향을 미치지 않습니다.
