→ 계약B보험회사 : 600만원 지급 = 1,000만원 × 3,000만원 / (2,000만원 + 3,000만원)
2. 다른 계약이 이 계약과 지급보험금의 계산방법이 다른 경우 :
계약A: 책임액 1,000만원 / 계약B: 책임액 1,000만원 / 손해액 : 1,000만원
