제8조 도난품의 귀속
회사가 보험금을 지급하였을 때에는 도난당한 보험의 목적에 대하여 보험금의 보험가액에 대
한 비율로 소유권을 가집니다. 그러나 피보험자는 그 보험금에 해당하는 금액을 회사에 내고
그 도난품의 소유권을 차지할 수 있습니다.

