정상적인 사용이 불가능한 상태를 말합니다.
③ 제1항의 수리는 해당 제품의 공식적인 국내 AS지정점에서 실제 수리하여 수리비를 지급한
경우에 한하며, 수리비는 부품비와 인건비 및 운반비(수리를 목적으로 AS지정점의 직원에
