4. 통상적인 마모와 균열, 잘못된 사용 또는 오·남용으로 인한 손해
5. 패임, 착색, 광택저하, 긁힘, 녹 등과 같이 제품의 기능에 아무런 영향을 주지 않는 외부
적 손상에 대한 손해
6. 제품의 조립이나 변경으로 발생한 모든 손해(절단, 톱질, 깎기 등을 포함)
7. 도난 , 분실 또는 망실로 인한 손해
8. 전쟁, 혁명, 내란, 사변, 폭동, 소요, 노동쟁의, 기타 이들과 유사한 사태로 생긴 화재 및
연소 또는 그 밖의 손해
9. 제품 고유의 결함, 설계결함 또는 법적조치로 인하여 제품의 리콜이나 변경으로 인해 발
생한 비용 손해
10. 제조사의 무상수리에 해당하는 손해.
11. 기록저장매체의 손상으로 인한 데이터 손실이나 소프트웨어의 문제로 인하여 발생하는
모든 비용 손해
12. 제조업자(제조업자가 지정한 수리업체를 포함)가 제품에 대하여 어떠한 결함도 발견하지
못한 경우에 발생한 모든 비용손해
13. 태풍, 홍수, 지진, 분화, 낙뢰 등 천재지변으로 인한 손해
14. 핵연료물질 또는 방사능 오염과 관련된 손해
15. 제품에 대한 청소나 주기적 점검, 관리에서 발생한 비용 손해
16. 필터, 전구(진공관 포함), 벨트, 잉크 등 교환이 필요한 소모품의 교환 비용
17. 제품보증서에 기재된 유상수리의 대상이 되는 고장유형으로 인한 손해. 단, 무상수리의
대상이 되는 고장 유형이 제품의 보증기간을 초과함으로써 유상수리의 대상이 된 경우에
는 보상합니다.
18. 보험의 목적(가전제품)의 임의 분해 및 개조로 인한 손해
19. 전기적/기계적 원인이 아닌 물리적 파손으로 인한 손해
