    ('KB손해보험_주택종합보험_05_제1조제2조', '[KB손해보험 / 주택종합보험 / 실화(대물)배상책임 특별약관] 제1조~제2조 용어의 정의', '[KB손해보험 / 주택종합보험 / 실화(대물)배상책임 특별약관] 제1조~제2조 용어의 정의
이 특별약관에서는 보통약관 제2조(용어의 정의) 제1호 ‘나‘목, 제2호 ‘가’목 및 ‘나’목을 아래
와 같이 대체하여 적용합니다.
1. 계약 관련 용어
나. 피보험자: 보험사고로 인하여 타인에 대한 법률상 손해배상책임을 부담하는 손해를 입
은 사람(법인인 경우에는 그 이사 또는 법인의 업무를 집행하는 그 밖의 기관)을 말합
니다.
2. 보상 관련 용어
가. 배상책임: 보험증권상의 보장지역 내에서 보험기간 중에 발생된 보험사고로 인하여 타
인에게 입힌 손해에 대한 법률상의 책임을 말합니다.
나. 보상한도액: 회사와 계약자간에 약정한 금액으로 피보험자가 법률상의 배상책임을 부
담함으로써 입은 손해 중 제6조(보험금 등의 지급한도)에 따라 회사가 책임지는 금액
의 최대한도를 말합니다.

제2조 보상하는 손해
회사는 피보험자가 보험증권에 기재된 주택 구내에서 보험기간 중에 발생한 화재사고로 인하
여 피해자의 재물을 망그러뜨려 법률적인 배상책임을 부담함으로써 입은 아래의 손해를 보상
하여 드립니다.
1. 피보험자가 피해자에게 지급할 책임을 지는 법률상 손해배상금
2. 계약자 또는 피보험자가 지출한 아래의 비용
가. 피보험자가 제9조(손해방지의무) 제1항 제1호의 손해의 방지 또는 경감을 위하여 지출
한 필요 또는 유익하였던 비용
나. 피보험자가 제9조(손해방지의무) 제1항 제2호의 제3자로부터 손해의 배상을 받을 수
있는 그 권리를 지키거나 행사하기 위하여 지출한 필요 또는 유익하였던 비용
【설명】
제3자로부터 손해의 배상을 받을수 있는 경우에 피보험자가 손해배상청구를 위해 내용증
명, 재산조사, 강제집행 등을 수행하고자 지출한 각종 비용을 의미합니다.
다. 피보험자가 지급한 소송비용, 변호사비용, 중재, 화해 또는 조정에 관한 비용
라. 보험증권상 보상한도액내의 금액에 대한 공탁보증보험료. 그러나 회사는 그러한 보증
을 제공할 책임은 부담하지 않습니다.
마. 피보험자가 제10조(손해배상청구에 대한 회사의 해결) 제2항 및 제3항의 회사의 요구
에 따르기 위하여 지급한 비용', 'KB손해보험', '주택종합보험', '동산', '실화(대물)배상책임 특별약관', NULL, '제1조~제2조', '용어의 정의', 1055, 422, 'high', NULL),
    ('KB손해보험_주택종합보험_05_제3조', '[KB손해보험 / 주택종합보험 / 실화(대물)배상책임 특별약관] 제3조 보상하지 않는 손해', '[KB손해보험 / 주택종합보험 / 실화(대물)배상책임 특별약관] 제3조 보상하지 않는 손해
회사는 아래의 사유로 인한 손해는 보상하지 않습니다.
1. 계약자 또는 피보험자 또는 이들의 법정대리인의 고의로 생긴 손해에 대한 배상책임
2. 전쟁, 혁명, 내란, 사변, 테러, 폭동, 소요, 노동쟁의 기타 이들과 유사한 사태로 생긴 손
해에 대한 배상책임
3. 지진, 분화, 홍수, 해일 또는 이와 유사한 천재지변으로 생긴 손해에 대한 배상책임
4. 피보험자가 소유, 점유, 임차, 사용하거나 보호, 관리, 통제(원인에 관계없이 모든 형태의
실질적인 통제행위를 포함합니다)하는 재물이 손해를 입었을 경우에는 그 재물에 대하여
정당한 권리를 가진 사람에게 부담하는 손해에 대한 손해배상 책임
5. 피보험자와 타인 간에 손해배상에 관한 약정이 있는 경우 그 약정에 의하여 가중된 손해
배상책임. 그러나 약정이 없었더라도 법률규정에 의하여 피보험자가 부담하게 될 배상책
임은 보상합니다.
6. 핵연료물질 또는 핵연료물질에 의하여 오염된 물질의 방사성, 폭발성 그 밖의 유해한 특
성 또는 이들의 특성에 의한 사고로 생긴 손해에 대한 배상책임
7. 위 제6호 이외의 방사선을 쬐는 것 또는 방사능 오염으로 인한 손해
