1. 계약 관련 용어
나. 피보험자: 보험사고로 인하여 타인에 대한 법률상 손해배상책임을 부담하는 손해를 입
은 사람(법인인 경우에는 그 이사 또는 법인의 업무를 집행하는 그 밖의 기관)을 말합
니다.
2. 보상 관련 용어
가. 배상책임: 보험증권상의 보장지역 내에서 보험기간 중에 발생된 보험사고로 인하여 타
인에게 입힌 손해에 대한 법률상의 책임을 말합니다.
나. 보상한도액: 회사와 계약자간에 약정한 금액으로 피보험자가 법률상의 배상책임을 부
담함으로써 입은 손해 중 제6조(보험금 등의 지급한도)에 따라 회사가 책임지는 금액
의 최대한도를 말합니다.

제2조 보상하는 손해
① 회사는 피보험자가 임차부동산(피보험자가 임차한 부동산으로서 보험증권에 기재된 것을 말
합니다)내에서 보험기간 중에 발생된 화재, 폭발, 파열로 인하여 그 부동산에 대하여 정당
한 권리를 가진 자에게 법률상의 배상책임을 부담함으로써 입은 아래의 손해를 이 약관에
따라 보상하여 드립니다.
1. 피보험자가 피해자에게 지급할 책임을 지는 법률상의 손해배상금
2. 계약자 또는 피보험자가 지출한 아래의 비용
가. 피보험자가 제10조(손해방지의무) 제1항 제1호의 손해의 방지 또는 경감을 위하여 지
출한 필요 또는 유익하였던 비용.
나. 피보험자가 제10조(손해방지의무) 제1항 제2호의 제3자로부터 손해의 배상을 받을 수
있는 그 권리를 지키거나 행사하기 위하여 지출한 필요 또는 유익하였던 비용
【설명】
제3자로부터 손해의 배상을 받을 수 있는 경우에 피보험자가 손해배상청구를 위해 내용증
명, 재산조사, 강제집행 등을 수행하고자 지출한 각종 비용을 의미합니다.
다. 피보험자가 지급한 소송비용, 변호사비용, 중재, 화해 또는 조정에 관한 비용
라. 보험증권상의 보상한도액내의 금액에 대한 공탁보증보험료. 그러나 회사는 그러한 보
증을 제공할 책임은 부담하지 않습니다.
마. 피보험자가 제11조(손해배상청구에 대한 회사의 해결)제2항 및 제3항의 회사의 요구에
