4. 피보험자와 타인 간에 손해배상에 관한 약정이 있는 경우, 그 약정에 의하여 가중된 배
상책임
5. 핵연료물질 또는 핵연료 물질에 의하여 오염된 물질의 방사성, 폭발성 그 밖의 유해한
특성 또는 이들의 특성에 의한 사고로 생긴 손해에 대한 배상책임
