가스로 인한 화재인 경우에 한하며, 원인불명인 경우는 보상하지 않습니다.
【폭발, 파열】
급격한 산화반응을 포함하는 파괴 또는 그 현상을 말합니다.
② 회사는 제1항에서 보장하는 위험으로 인하여 손해가 발생한 경우 계약자 또는 피보험자가
지출한 아래의 비용을 추가로 지급합니다.
1. 잔존물 제거비용 : 사고현장에서의 잔존물의 해체비용, 청소비용 및 차에 싣는 비용. 다
만, 제1항에서 보장하지 않는 위험으로 보험의 목적이 손해를 입거나 관계법령에 의하여
제거됨으로써 생긴 손해에 대하여는 보상하여 드리지 않습니다.
2. 손해방지비용 : 손해의 방지 또는 경감을 위하여 지출한 필요 또는 유익한 비용
3. 대위권 보전비용 : 제3자로부터 손해의 배상을 받을 수 있는 경우에는 그 권리를 지키거
나 행사하기 위하여 지출한 필요 또는 유익한 비용
4. 잔존물 보전비용 : 잔존물을 보전하기 위하여 지출한 필요 또는 유익한 비용. 다만, 제13
조(잔존물)에 의해 회사가 잔존물을 취득한 경우에 한합니다.
5. 기타 협력비용 : 회사의 요구에 따르기 위하여 지출한 필요 또는 유익한 비용
【청소비용】
사고현장 및 인근 지역의 토양, 대기 및 수질 오염물질 제거비용과 차에 실은 후 폐기물
처리비용은 포함되지 않습니다.
