회사는 아래의 사유로 인한 손해는 보상하여 드리지 않습니다.
1. 계약자, 피보험자 또는 이들의 법정대리인의 고의 또는 중대한 과실
2. 지진 또는 분화 등의 천재지변으로 생긴 손해
3. 전쟁, 외국의 무력행사, 혁명, 내란, 사변, 폭동, 테러 또는 기타 이들과 유사한 사태로
생긴 손해. 단, 소요, 노동쟁의로 보험의 목적에 생긴 손해는 보상합니다. 여기서 소요라
함은 사변 및 폭동에 이르지 못하는 정치적 또는 사회적 소요를 말합니다.
4. 핵연료물질 또는 핵연료 물질에 의하여 오염된 물질의 방사성, 폭발성 그 밖의 유해한
특성 또는 이들의 특성에 의한 사고로 인한 손해 또는 방사선을 쬐는 것 또는 방사능 오
염으로 인한 손해
5. 태풍, 회오리바람, 폭풍, 폭풍우, 홍수, 해일, 범람 및 이와 비슷한 풍재 또는 수재로 보
험의 목적에 생긴 손해. 단, 건물에 부착된 유리는 풍재 또는 수재로 인한 손해를 보상하
며, 수조, 급배수설비(급배수설비에는 스프링클러나 설비나 자동적으로 작동하는 소화용
살수장치로서 헤드, 배관, 경보장치, 탱크, 펌프 및 이의 부속기구는 포함하지 않음) 또
는 수관(이하 「급배수설비」)이 우연한 사고로 인해 누수 또는 방수됨에 따라 보험의
목적에 생긴 손해는 보상합니다.
6. 자연발열, 자연발화, 마모, 내재적 결함, 재질 변경, 녹 및 부식, 누설, 쥐, 곤충, 해충,
기후·온도 조건의 변화, 통상적인 해수면의 변화, 기타 점진적으로 작용하는 원인으로 생
긴 손해. 단, 자연발열 또는 자연발화로 연소된 다른 보험의 목적에 생긴 손해는 보상하
여 드립니다.
7. 법률적으로 또는 실질적으로 정부 및 공공기관의 행위나 명령에 의한 몰수, 국유화, 징
발, 파괴 또는 손상으로 생긴 손해
8. 공공설비(전기, 가스, 통신, 수도 또는 기타 에너지원)의 공급불능, 불량으로 발생한 손해
9. 도난, 망실 또는 분실 손해. 그러나 절도 또는 강도행위로 발생한 건물의 파손 손해는 보
상합니다.
10. 외부적 힘에 의하지 않은 부속설비 및 가재에 생긴 손해
11. 피보험자나 고용인의 잘못된 운영이나 잘못된 기술로 인하여 전기․기계장비에 생긴 손해
12. 가재 또는 유리(건물에 부착된 유리 제외)의 파손손해. 그러나 화재, 낙뢰, 폭발, 붕괴,
사태, 자동차나 항공기와의 충돌, 항공기로부터 낙하물체와의 충돌, 소요, 노동쟁의, 피
보험자 또는 이들 법정대리인이 아닌 자의 고의적이고 악의적인 행위로 인한 파손손해는
보상합니다.
13. 발전기, 여자기(정류기 포함), 변류기, 변압기, 전압조정기, 축전기, 개폐기, 차단기, 피뢰
기, 배전반 및 그 밖의 전기기기 또는 장치의 전기적 사고로 생긴 손해는 보상하지 않
음. 단, 그 결과로 생긴 손해는 보상하여 드립니다.
14. 기관, 기기, 증기기관, 내연기관, 유압기 등의 물리적인 폭발, 파열이나 기계의 운동부분
또는 회전부분이 분해되어 날아 흩어짐으로 인해 생긴 손해
