험료는 변경적용하지 않습니다. 다만, 보통약관 제16조(계약 후 알릴 의무)에 따라 보험료
가 변경된 경우에는 예외로 합니다.

제2조 준용규정
이 특별약관에 정하지 않은 사항은 보통약관을 따릅니다.', 'KB손해보험', '주택종합보험', '동산', '보험료분납 특별약관', NULL, '제1조~제2조', '제2회 이후 보험료의 납입', 449, 179, 'high', NULL),
    ('KB손해보험_주택종합보험_13_제1조제2조제3조제4조', '[KB손해보험 / 주택종합보험 / 보험기간설정 추가특별약관] 제1조~제2조~제3조~제4조 적용범위', '[KB손해보험 / 주택종합보험 / 보험기간설정 추가특별약관] 제1조~제2조~제3조~제4조 적용범위
이 추가특별약관은 보통약관 제46조(보험의 목적의 증가 감소 또는 교체) 제2항에도 불구하고,
새로이 증가되는 피보험자의 보험기간을 정하는 경우에 적용합니다.

제2조 보험기간
이 추가특별약관에 따라 계약기간 중에 새로이 증가된 피보험자의 보험기간은 계약자가 요청
하는 기간으로 합니다.

제3조 보험료의 납입
① 계약자는 새로이 증가된 피보험자에 대하여 일단위로 계산된 추가보험료를 납입하여야 합
니다.
② 새로이 증가된 피보험자의 보험기간이 시작된 후라도 다른 약정이 없으면 추가 보험료를
받기 전에 생긴 손해는 보상하여 드리지 않습니다.

제4조 준용규정
이 추가특별약관에 정하지 않은 사항은 보통약관 및 보험료분납 특별약관을 따릅니다.', 'KB손해보험', '주택종합보험', '동산', '보험기간설정 추가특별약관', NULL, '제1조~제2조~제3조~제4조', '적용범위', 414, 165, 'high', NULL),
    ('KB손해보험_주택종합보험_14_제1조제2조제3조제4조', '[KB손해보험 / 주택종합보험 / 보험료 자동납입 특별약관] 제1조~제2조~제3조~제4조 보험료의 납입', '[KB손해보험 / 주택종합보험 / 보험료 자동납입 특별약관] 제1조~제2조~제3조~제4조 보험료의 납입
계약자는 제2회 이후의 보험료부터 이 특별약관에 따라 계약자의 거래은행 지정계좌를 이용하
여 보험료를 자동 납입합니다.

제2조 보험료의 영수
자동납입일자는 이 청약서에 기재된 보험료 납입해당일에도 불구하고 매월 회사가 정하는 날
중 계약자가 희망하는 일자로 합니다.

제3조 계약 후 알릴 의무
계약자는 지정계좌의 번호가 변경 또는 거래 정지된 경우에는 이 사실을 즉시 회사에 알려야
합니다.

제4조 준용규정
이 특별약관에 정하지 않은 사항은 해당 특별약관을 따릅니다.', 'KB손해보험', '주택종합보험', '동산', '보험료 자동납입 특별약관', NULL, '제1조~제2조~제3조~제4조', '보험료의 납입', 322, 128, 'high', NULL),
    ('KB손해보험_주택종합보험_15_제1조제2조제3조', '[KB손해보험 / 주택종합보험 / 초회보험료 자동납입 추가특별약관] 제1조~제2조~제3조 보험료의 납입', '[KB손해보험 / 주택종합보험 / 초회보험료 자동납입 추가특별약관] 제1조~제2조~제3조 보험료의 납입
① 계약자는 제1회 보험료의 납입방법을 계약자의 거래은행 지정계좌를 통한 자동납입으로 가
입하고자 하는 경우에, 회사는 청약서를 접수하고 자동이체신청에 필요한 정보를 제공한 때
(다만, 계약자의 책임있는 사유로 보험료의 납입이 불가능한 경우에는 거래은행의 지정계좌
로부터 제1회 보험료가 이체된 날을 기준으로 합니다)를 청약일 및 제1회 보험료 납입일로
하여 보통약관 제18조(보험계약의 성립)의 규정을 적용합니다.
② 제1항의 경우에 회사는 청약서를 접수한 날로부터 30일 이내에 승낙 또는 거절하여야 하
며, 승낙한 때에는 금융기관의 해당계좌에서 제1회 보험료를 받고 보험증권을 드립니다.

제2조 계약 후의 알릴 의무
계약자는 지정계좌의 번호가 변경 또는 거래정지된 경우에는 이 사실을 즉시 회사에 알려야
합니다.

제3조 준용규정
