① 이 상품다수구매자 보험계약 특별약관(이하 “특별약관”이라 합니다)은 상품판매자가 자기의
관리 하에 운영, 유지되는 상품구매자 다수를 피보험자로 하여 보험계약을 체결하는 경우에
적용합니다.
② 제1항의 상품구매자란 각종 재화, 용역 및 서비스의 구매자를 말합니다.
③ 제1항의 총 피보험자수는 100인 이상이어야 합니다.

제2조 계약자
이 특별약관의 계약자는 제1조(계약의 적용범위)의 상품구매자 다수를 대표하는 보험계약상의
모든 권리, 의무를 행사할 수 있어야 합니다.

제3조 보험가입금액
피보험자의 보험가입금액은 동일하게 책정하는 것을 원칙으로 합니다.

제4조 피보험자의 증가, 감소 또는 교체
① 보험계약을 맺은 후 피보험자를 증가, 감소 또는 교체하고자 하는 경우에는 계약자 또는 피
보험자는 지체없이 서면으로 그 사실을 회사에 알리고 회사의 승인을 받아야 합니다.
② 이 계약기간 중 피보험자 감소의 경우는 당해 피보험자의 계약은 해지된 것으로 하며, 새
로이 증가 또는 교체되는 피보험자의 보험기간은 이 계약의 남은 보험기간으로 하고 이로
인하여 발생되는 추가 또는 환급보험료는 일단위로 계산하여 받거나 돌려 드립니다.
③ 회사는 제1항 및 제2항을 위반하였을 경우에 새로이 증가 또는 교체되는 해당 피보험자에
대하여는 보상하여 드리지 않습니다.', 'KB손해보험', '주택종합보험', '동산', '상품다수구매자 보험계약 특별약관', NULL, '제1조~제2조~제3조~제4조', '계약의 적용범위', 714, 285, 'high', NULL),
