관계없이 보험료가 정산되기 이전일지라도 새로이 증가 또는 교체된 피보험자에 대해 생긴
손해를 보상하여 드립니다.

제2조 피보험자의 명부
보험계약자는 항상 피보험자의 명부를 비치하여 회사가 열람을 요구할 경우에는 이에 따라야
합니다.

제3조 보험료의 정산방법
보험료는 피보험자수의 증감을 기초로 하여 다음과 같이 정산합니다.
1. 보험계약자는 매월 10일까지 전월말까지의 피보험자에 관한 서류를 회사에 제출하여야
합니다. 그러나 계약이 효력상실 또는 해지된 경우에는 효력상실 또는 해지일까지의 보
험료를 확정하기 위하여 필요한 서류를 효력상실 또는 해지 즉시 회사에 제출하여야 합
니다.
2. 회사는 보험기간중이나 보험기간 만료 후 보험료를 산출하기 위하여 필요하다고 인정될
경우에는 보험계약자의 서류를 열람할 수 있습니다.
3. 회사는 보험기간 만료와 동시에 피보험자수에 따라 산출된 확정보험료와 계약체결시 산
출한 예치보험료를 비교하여 그 차액을 정산합니다.', 'KB손해보험', '주택종합보험', '동산', '보험료정산 추가특별약관', NULL, '제1조~제2조~제3조', '보험료의 정산', 672, 268, 'high', NULL),
