는 경우에는 이 특약은 더 이상 효력을 가지지 않습니다.

제3조 지정대리청구인의 지정
① 계약자는 보통약관 또는 특별약관에서 정한 보험금을 직접 청구할 수 없는 특별한 사정이
있을 경우를 대비하여 계약체결시 또는 계약체결 이후 다음 각 호의 어느 하나에 해당하는
자 중에서 보험금의 청구대리인(2인 이내에서 지정하되, 2인 지정시 대표대리인을 지정)(이
하 “지정대리청구인”이라 합니다)으로 지정할 수 있습니다. 또한 지정대리청구인은 제4조
(지정대리청구인의 변경지정)에 의한 변경지정 또는 보험금 청구시에도 다음 각호의 어느
