하는 서류를 제출하고 회사의 승낙을 얻어 제1조(적용대상)의 보험수익자(보험금을 받는
자)의 대리인으로서 보험금(사망보험금 제외)을 청구하고 수령할 수 있습니다. 다만, 2인의
