제657조 보험사고발생의 통지의무
① 보험계약자 또는 피보험자나 보험수익자는 보험사고의 발생을 안 때에는 지체없이 보험자
에게 그 통지를 발송하여야 한다.
② 보험계약자 또는 피보험자나 보험수익자가 제1항의 통지의무를 해태함으로 인하여 손해가
증가된 때에는 보험자는 그 증가된 손해를 보상할 책임이 없다.

제735조 
의3(단체보험)
① 단체가 규약에 따라 구성원의 전부 또는 일부를 피보험자로 하는 생명보험계약을 체결하는
경우에는 제731조를 적용하지 아니한다.
② 제1항의 보험계약이 체결된 때에는 보험자는 보험계약자에 대하여서만 보험증권을 교부한
다.
③ 제1항의 보험계약에서 보험계약자가 피보험자 또는 그 상속인이 아닌 자를 보험수익자로
지정할 때에는 단체의 규약에서 명시적으로 정하는 경우 외에는 그 피보험자의 제731조제1
항에 따른 서면 동의를 받아야 한다.
