이 계약에서 사용되는 용어의 정의는 이 계약의 다른 조항에서 달리 정의되지 않는 한 다음과
같습니다. 1. 계약 관련 용어
가. 계약자: 회사와 계약을 체결하고 보험료를 납입할 의무를 지는 사람을 말합니다. 나. 피보험자: 보험사고로 인하여 손해를 입은 사람(법인인 경우에는 그 이사 또는 법인의
업무를 집행하는 그 밖의 기관)을 말합니다. 다. 보험증권: 계약의 성립과 그 내용을 증명하기 위하여 회사가 계약자에게 드리는 증서
를 말합니다. 라. 보험의 목적: 이 약관에 따라 보험에 가입한 물건으로 보험증권에 기재된 건물 등을
말합니다. (ⅰ) 주택으로만 쓰이는 건물 중 다음의 것 또는 그 수용가재
- 단독주택
- 주택의 부속건물로서 가재만을 수용하는데 쓰이는 것
- 연립(다세대)주택, 아파트(주상복합아파트의 주거용도 부분 포함)로서 각 호(戶), 실
(室)이 모두 주택으로만 쓰이는 것
(ⅱ) 주택병용 물건으로서 아래의 용도로 사용하는 건물 및 그 수용가재
- 교습소(피아노, 꽃꽂이, 국악, 재봉 및 이와 비슷한 것)
- 치료(안수, 침구(침질, 뜸질), 정골, 조산원 및 이와 비슷한 것)
2. 보상 관련 용어
가. 보험가입금액: 회사와 계약자간에 약정한 금액으로 보험사고가 발생할 때 회사가 지급
할 최대 보험금을 말합니다. 나. 보험가액: 재산보험에 있어 피보험이익을 금전으로 평가한 금액으로 보험목적에 발생
할 수 있는 최대 손해액을 말합니다.(회사가 실제 지급하는 보험금은 보험가액을 초과
할 수 없습니다)
【설명】
보험목적물이 건물인 경우, 보험가액은 통상적으로 손해가 발생된 때와 장소에서의 재조달
가액에서 감가상각액을 제외한 금액으로 보험사와 계약자가 약정한 금액인 보험가입금액과
구별됩니다. 다. 자기부담금: 보험사고로 인하여 발생한 손해에 대하여 계약자 또는 피보험자가 부담하
는 일정 금액을 말합니다. 라. 보험금 분담: 이 계약에서 보장하는 위험과 같은 위험을 보장하는 다른 계약(공제계약
을 포함합니다)이 있을 경우 비율에 따라 손해를 보상합니다. 【공제계약】
공제계약이란 동일한 직업 또는 사업에 종사하는 다수의 주체가 상호구제를 위하여 보험
료에 상당하는 금전을 납입하고 그 가입자에게 소정의 사고가 발생한 경우 공동의 구제를
하는 계약으로, 가입자의 범위가 구성원 또는 특정 지역으로 한정됩니다. 마. 대위권: 회사가 보험금을 지급하고 취득하는 법률상의 권리를 말합니다. 3. 이자율 관련 용어
가. 연단위 복리: 회사가 지급할 금전에 이자를 줄 때 1년마다 마지막 날에 그 이자를 원
금에 더한 금액을 다음 1년의 원금으로 하는 이자 계산방법을 말합니다. 나. 보험개발원이 공시하는 보험계약대출이율: 보험개발원이 정기적으로 산출하여 공시하
는 이율로써 회사가 보험금의 지급 또는 보험료의 환급을 지연하는 경우 등에 적용합
니다. 4. 기간과 날짜 관련 용어
가. 보험기간: 계약에 따라 보장을 받는 기간을 말합니다. 나.', 'KB손해보험', '주택종합보험_(주택)', '동산', 'KB주택화재보험 보통약관', '제1관 목적 및 용어의 정의', '제2조', '용어의 정의', 1486, 594, 'high', NULL),
