① 회사는 보험의 목적이 화재, 폭발, 또는 파열(이하 「사고」라 합니다)로 입은 아래의 손해
를 보상하여 드립니다.
1. 사고에 따른 직접손해
2. 사고에 따른 소방손해(화재진압과정에서 발생하는 손해)
3. 사고에 따른 피난손해(피난지에서 5일 동안에 보험의 목적에 생긴 위 제1호 및 제2호의
손해를 포함합니다)
【폭발, 파열】
급격한 산화반응을 포함하는 파괴 또는 그 현상을 말합니다.
② 회사는 제1항에서 보장하는 위험으로 인하여 손해가 발생한 경우 계약자 또는 피보험자가
지출한 아래의 비용을 추가로 지급합니다.
1. 잔존물 제거비용 : 사고현장에서의 잔존물의 해체비용, 청소비용 및 차에 싣는 비용. 다
만, 제1항에서 보장하지 않는 위험으로 보험의 목적이 손해를 입거나 관계법령에 의하여
제거됨으로써 생긴 손해에 대하여는 보상하여 드리지 않습니다.
2. 손해방지비용 : 손해의 방지 또는 경감을 위하여 지출한 필요 또는 유익한 비용
3. 대위권 보전비용 : 제3자로부터 손해의 배상을 받을 수 있는 경우에는 그 권리를 지키거
나 행사하기 위하여 지출한 필요 또는 유익한 비용
4. 잔존물 보전비용 : 잔존물을 보전하기 위하여 지출한 필요 또는 유익한 비용. 다만, 제13
조(잔존물)에 의해 회사가 잔존물을 취득한 경우에 한합니다.
5. 기타 협력비용 : 회사의 요구에 따르기 위하여 지출한 필요 또는 유익한 비용
【청소비용】
사고현장 및 인근 지역의 토양, 대기 및 수질 오염물질 제거비용과 차에 실은 후 폐기물
처리비용은 포함되지 않습니다.
③ 아래의 물건은 보험증권에 기재하여야만 제1항의 보험의 목적이 됩니다.
1. 통화, 유가증권, 인지, 우표 및 이와 비슷한 것
2. 귀금속, 귀중품, 보옥, 보석, 글․그림, 골동품, 조각물 및 이와 비슷한 것
3. 원고, 설계서, 도안, 물건의 원본, 모형, 증서, 장부, 금형(쇠틀), 목형(나무틀), 소프트웨
어 및 이와 비슷한 것
4. 실외 및 옥외에 쌓아둔 동산
【귀중품】
무게나 부피가 휴대할 수 있으며, 점당 300만원 이상
④ 아래의 물건은 다른 약정이 없으면 제1항의 보험의 목적에 포함됩니다.
1. 건물인 경우
가. 건물의 부속물 : 피보험자의 소유인 칸막이, 대문, 담, 곳간 및 이와 비슷한 것
나. 건물의 부착물 : 피보험자 소유인 간판, 네온사인, 안테나, 선전탑 및 이와 비슷한 것
다. 건물의 부속설비 : 피보험자의 소유인 전기, 가스, 난방, 냉방설비 및 이와 비슷한 것
2. 건물이외 경우: 피보험자 또는 그와 같은 세대에 속하는 사람의 소유물(생활용품, 집기·
