회사는 아래의 사유로 인한 손해는 보상하여 드리지 않습니다.
1. 계약자, 피보험자 또는 이들의 법정대리인의 고의 또는 중대한 과실
2. 화재, 폭발 또는 파열이 발생했을 때의 분실로 생긴 손해
3. 보험의 목적의 발효, 자연발열, 자연발화로 생긴 손해. 그러나, 자연발열 또는 자연발화
로 연소된 다른 보험의 목적에 생긴 손해는 보상하여 드립니다.
4. 화재, 폭발 또는 파열로 인하지 않은 수도관, 수관 또는 수압기 등의 파열로 생긴 손해
5. 발전기, 여자기(정류기 포함), 변류기, 변압기, 전압조정기, 축전기, 개폐기, 차단기, 피뢰
기, 배전반 및 그 밖의 전기기기 또는 장치의 전기적 사고로 생긴 손해. 그러나 그 결과
로 생긴 화재, 폭발, 파열손해는 보상하여 드립니다.
6. 원인의 직접, 간접을 묻지 않고 지진, 분화 또는 전쟁, 혁명, 내란, 사변, 폭동, 소요, 노
동쟁의, 기타 이들과 유사한 사태로 생긴 화재 및 연소 또는 그 밖의 손해
7. 핵연료물질 또는 핵연료물질에 의하여 오염된 물질의 방사성, 폭발성 그 밖의 유해한 특
성 또는 이들의 특성에 의한 사고로 인한 손해
8. 위 제7호 이외의 방사선을 쬐는 것 또는 방사능 오염으로 인한 손해
9. 국가 및 지방자치단체의 명령에 의한 재산의 소각 및 이와 유사한 손해
【핵연료물질】
사용된 연료를 포함합니다.
