① 보험의 목적에 손해가 생긴 경우 계약자 또는 피보험자는 지체없이 이를 회사에 알려야 합
니다.
② 계약자 또는 피보험자가 제1항의 통지를 게을리하여 손해가 증가된 때에는 회사는 그 증가
된 손해는 보상하여 드리지 않습니다.
③ 회사가 제1항에 대한 손해의 사실을 확인하기 어려운 경우에는 계약자 또는 피보험자에게
필요한 증거자료의 제출을 요청할 수 있습니다.
④ 회사는 제1항의 통지를 받은 때에는 사고가 생긴 건물 또는 그 구내와 거기에 들어있는 피
보험자의 소유물을 조사할 수 있습니다.

제6조 보험금의 청구
피보험자가 보험금을 청구할 때에는 다음의 서류를 회사에 제출하여야 합니다.
1. 보험금 청구서(회사양식)
2. 신분증(주민등록증이나 운전면허증 등 사진이 붙은 정부기관발행 신분증, 본인이 아닌 경
우에는 본인의 인감증명서, 본인서명사실확인서 또는 안전성과 신뢰성이 확보된 전자적
수단을 활용한 피보험자 의사표시의 확인방법 포함)
3. 기타 회사가 요구하는 증거자료

제7조 보험금의 지급절차
① 회사는 제6조(보험금의 청구)에서 정한 서류를 접수한 때에는 접수증을 교부하고, 그 서류
를 접수받은 후 지체없이 지급할 보험금을 결정하고 지급할 보험금이 결정되면 7일 이내에
이를 지급하여 드립니다. 또한, 지급할 보험금이 결정되기 전이라도 피보험자의 청구가 있
을 때에는 회사가 추정한 보험금의 50% 상당액을 가지급보험금으로 지급합니다.
【가지급보험금】
보험금이 지급기한 내에 지급되지 못할 것으로 판단되는 경우 회사가 예상되는 보험금의
일부를 먼저 지급하는 제도로 피보험자가 필요로 하는 비용을 보전해 주기 위해 회사가
먼저 지급하는 임시 교부금을 말합니다.
② 회사가 제1항의 규정에 정한 지급기일 내에 보험금을 지급하지 않았을 때에는 그 다음날부
터 지급일까지의 기간에 대하여 <부표> ‘보험금을 지급할 때의 적립이율’에 따라 연단위 복
리로 계산한 금액을 보험금에 더하여 지급합니다. 그러나 계약자 또는 피보험자의 책임 있
는 사유로 지급이 지연될 때에는 그 해당기간에 대한 이자를 더하여 지급하지 않습니다.
