우에는, 회사는 14일(보험기간이 1년 미만인 경우에는 7일) 이상의 기간을 납입최고(독촉)
기간으로 정하여 계약자(타인을 위한 계약의 경우 그 특정된 타인을 포함합니다)에게 다음
의 내용을 서면(등기우편 등), 전화(음성녹음) 또는 전자문서 등으로 알려드립니다. 다만,
계약이 해지되기 전에 발생한 보험금 지급사유에 대하여 회사는 계약상의 보장을 합니다.
1. 납입최고(독촉)기간 내에 연체보험료를 납입하여야 한다는 내용
2. 납입최고(독촉)기간이 끝나는 날까지 보험료를 납입하지 않을 경우 그 끝나는 날의 다음
