② 제1항의 납입최고(독촉)기간은 납입최고(독촉)의 통지가 계약자(타인을 위한 계약의 경우에
는 그 특정된 타인을 포함)에게 도달한 날부터 시작되며, 납입최고(독촉)기간의 마지막 날이
영업일이 아닌 때에는 최고(독촉)기간은 그 다음 날까지로 합니다.
