면에 의한 동의를 얻어 수신확인을 조건으로 전자문서를 송신하여야 하며, 계약자가 전자문
서에 대하여 수신을 확인하기 전까지는 그 전자문서는 송신되지 않은 것으로 봅니다. 회사
는 전자문서가 수신되지 않은 것으로 확인되는 경우에는 제1항의 납입최고(독촉)기간을 설
정하여 제1항에서 정한 내용을 서면(등기우편 등) 또는 전화(음성녹음)로 다시 알려 드립니다.
④ 회사가 제1항에 따른 납입최고(독촉) 등을 전화(음성녹음)로 안내하고자 할 때 다음 각 호
의 요건을 모두 충족하는 경우에 「보험업감독규정」 제4-36조 제3항에 따른 전자적 상품
설명장치를 활용할 수 있습니다.
