보호에 관한 법률｣, 상법, 민법 등 관계 법령을 따릅니다.

제42조 예금보험에 의한 지급보장
회사가 파산 등으로 인하여 보험금 등을 지급하지 못할 경우에는 예금자보호법에서 정하는 바
에 따라 그 지급을 보장합니다.
【설명】
예금자보호제도란 예금자보호법에 의해 설립된 예금보험공사가 평소에 금융회사로부터
보험료를 받아 기금을 적립한 후, 금융회사가 영업정지나 파산 등으로 예금을 지급할 수
없게 되면 금융회사를 대신하여 예금을 지급하는 제도를 말합니다.
이 보험계약은 예금자보호법에 따라 해약환급금(또는 만기 시 보험금)에 기타지급금을 합
한 금액이 1인당 “1억원까지”(본 보험회사의 여타 보호 상품과 합산) 보호됩니다. 이와
별도로 본 보험회사 보호상품의 사고보험금을 합산한 금액이 1인당 “1억원까지” 보호됩
니다. 다만, 보험계약자 및 보험료 납부자가 법인인 보험계약의 경우에는 보호되지 않습
니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', 'KB주택화재보험 보통약관', '제7관 분쟁의 조정 등', '제41조~제42조', '준거법', 555, 222, 'high', NULL),
    ('KB손해보험_주택종합보험_(주택)_00_제43조', '[KB손해보험 / 주택종합보험_(주택) / 제7관 분쟁의 조정 등] 제43조 추가조항', '[KB손해보험 / 주택종합보험_(주택) / 제7관 분쟁의 조정 등] 제43조 추가조항
보험계약 및 물건의 성질에 따라 다음의 추가조항이 적용됩니다.
① 소화설비 추가조항
보험의 목적인 건물에 시설된 소화설비가 검사에 합격하여 소정의 할인율을 적용받는 경우
계약자 또는 피보험자는 보험기간 중에 이 설비를 늘 유효하게 보존하여야 하며, 이 설비가
조사기준에 미달하거나 기능이 정지 또는 감소된 때에는 그 사실을 회사에 정당한 이유없이
지연되지 않도록 알리고 정해진 추가보험료를 내어야 합니다.
② 공지할인 추가조항
보험의 목적에 대하여 소정의 공지할인이 적용된 경우 계약자 또는 피보험자는 보험기간 중
에 정해진 공지거리가 좁혀진 때에는 회사에 정당한 이유없이 지연되지 않도록 그 사실을 알
리고 추가보험료를 내어야 합니다.
【공지할인】
공지거리가 일정거리 이상인 경우 보험료를 할인하여 드립니다.
【공지거리】
두 건물의 가장 가까운 벽 사이의 거리를 말합니다. 다만, 외벽이 없는 경우에는 기둥과
기둥사이를 연결한 선을 외벽면으로 봅니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', 'KB주택화재보험 보통약관', '제7관 분쟁의 조정 등', '제43조', '추가조항', 525, 210, 'high', NULL),
