없음으로 인해 발생되는 모든 형태의 직접 또는 간접손해를 보상하지 않습니다.
② 회사는 위와 관련한 결함, 논리체계 등을 교정하기 위한 정보처리시스템(EDPS) 또는 그 관
련기기 일부분을 수리하거나 수정하는 비용은 보상하지 않습니다.
③ 회사는 상기 제1항에 기술한 것과 같은 날짜와 관련된 잠재적인 또는 실제적인 고장, 오작
