제2조 보상하지 않는 손해
① 회사는 실제 또는 발생이 예견되는 테러사고를 저지 또는 방어하는 행위를 포함하는 테러행
위로 인한 직접적 또는 간접적으로 발생한 손해액을 보상하지 않습니다. 동시적 또는 연속
적으로 테러행위로 귀결되는 여타의 원인 또는 행위와 상관없이 그 손해액은 보상하지 않
습니다.
② 제1조(용어의 정의) 제1호, 제2호 이외에 아래의 테러행위로 인한 손해액을 보상하지 않습
니다.
1. 직접적 또는 간접적인 핵반응, 방사능 또는 방사능 오염으로 귀결되는 핵물질의 사용, 방
출 또는 유출과 관련된 행위
