2. 보상 관련 용어
가. 배상책임: 보험증권상의 보장지역 내에서 보험기간 중에 발생된 보험사고로 인하여 타
인에게 입힌 손해에 대한 법률상의 책임을 말합니다.
나. 보상한도액: 회사와 계약자간에 약정한 금액으로 피보험자가 법률상의 배상책임을 부
담함으로써 입은 손해 중 제5조(보험금의 지급과 보상한도)에 따라 회사가 책임지는
금액의 최대한도를 말합니다.
② 이 특별약관에서 사용하는 용어의 정의는 아래와 같습니다.
1. 특수건물이라 함은 화재로 인한 재해보상과 보험가입에 관한 법률(이하「법」이라 합니
다) 제2조 제3호와 동법시행령(이하「시행령」이라 합니다) 제2조 제1항에서 정하는 건
물을 말합니다.
2. 건물소유자손해배상책임이라 함은 법 제4조 제1항에서 정하는 배상책임 및 파열 또는 폭
발로 인한 민법상의 손해배상책임을 말합니다.
3. 타인이라 함은 특수건물의 소유자 및 그 주거를 같이하는 직계가족(법인인 경우에는 이
사 또는 업무집행기관) 이외의 사람을 말합니다.
