4. 핵연료물질 또는 핵연료물질에 의해서 오염된 물질의 방사성, 폭발성, 그 밖의 유해한 특
성 또는 이들의 특성으로 생긴 사고
5. 제4호 이외의 방사선을 쬐는 것 또는 방사능 오염으로 생긴 손해
