행규칙 제2조에 따라 결정
2. 제1항 제2호 ‘가’목, ‘나’목 및 ‘마‘목 : 피보험자가 지급한 비용의 전액
3. 제1항 제2호 ‘다’목 및 ‘라’목 : 이 비용과 제1호에 의한 보상액의 합계액을 보험증권상
에 기재된 보상한도액내에서 보상
