직접 청구할 수 있습니다. 그러나 회사는 피보험자가 그 사고에 관하여 가지는 항변으로써
피해자에게 대항할 수 있습니다.
【설명】
회사는 피보험자가 손해배상액의 전부 또는 일부를 피해자에게 지급하지 않아도 되는 사유
가 있는 경우에는 그에 해당하는 보험금의 지급을 거절할 수 있습니다.
② 회사가 위 제1항의 청구를 받았을 때에는 정당한 이유없이 지연되지 않도록 피보험자에게
통지하여야 하며, 회사의 요구가 있으면 계약자 및 피보험자는 필요한 서류증거의 제출, 증
언 또는 증인출석에 협조하여야 합니다.
③ 피보험자가 피해자로부터 손해배상의 청구를 받았을 경우에 회사가 필요하다고 인정할 때에
는 피보험자를 대신하여 회사의 비용으로 이를 해결할 수 있습니다. 이 경우에 회사의 요구
가 있으면 계약자 또는 피보험자는 이에 협력하여야 합니다.
④ 계약자 및 피보험자가 정당한 이유없이 제2항, 제3항의 요구에 협조하지 않은 때에는 회사
는 그로 인하여 늘어난 손해는 보상하여 드리지 않습니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '지진위험 특별약관', NULL, '제7조', '손해배상청구에 대한 회사의 해결', 652, 260, 'high', NULL),
