제4조 보험가입금액 및 지급보험금의 계산
① 보험가입금액은 보험의 목적의 재조달가액의 80%를 상회하여야 합니다.
② 회사가 지급하여야 할 보험금은 아래에 따라 계산합니다.
1. 보험가입금액이 보험의 목적의 재조달가액의 80% 해당액과 같거나 클 때 : 보험가입금
액을 한도로 재조달가액기준 손해액 전액
2. 보험가입금액이 보험의 목적의 재조달가액의 80% 해당액보다 작을 때 : 보험가입금액을
한도로 아래의 금액
보험가입금액
재조달가액 기준의 손해액 ×
재조달가액
