1. 피해재산에 대한 보험가입금액
2. 피해재산과 용도 및 성능이 같다고 인정되는 재산의 전부 또는 일부의 재조달가액
3. 피해재산의 수리 또는 복구에 실제로 소요된 금액
④ 회사는 보험의 목적이 손해를 입은 장소에서 실제로 수리 또는 복구되지 않은 때에는 재조
달가액에 의한 보상을 하지 않고 보통약관 제9조(지급보험금의 계산)에 정한 바에 따라 시
가(감가상각된 금액)만을 보상합니다. 계약자 또는 피보험자는 손해발생 후 늦어도 180일
