1. 글·그림, 골동품, 조각물 및 기타 이와 비슷한 것
2. 원고, 설계서, 도안, 물건의 원본, 모형, 증서, 장부, 금형, 목형, 소프트웨어 및 기타 이
와 비슷한 것

제2조 보험가액
보통약관 제11조(손해액의 조사결정)의 규정에도 불구하고 이 특별약관이 첨부된 계약에 있어
서는 계약체결시 회사는 계약자 또는 피보험자와 보험의 목적의 가액을 협의하여 평가하고 그
금액을 보험기간 중의 보험가액으로 합니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '협정보험가액 특별약관', NULL, '제1조~제2조', '보험의 목적', 325, 130, 'high', NULL),
