의 보험가액을 보험가입금액으로 하여 보험증권에 기재합니다.

제4조 알릴 의무
① 계약을 맺을 때에는 같은 보험의 목적에 대하여 이 특별약관이 첨부된 다른 계약 또는 이
특별약관이 첨부되지 않은 다른 계약(이하「다수보험계약」이라 합니다)을 맺을 경우에는
계약자, 피보험자 또는 이들의 대리인은 반드시 그 사실을 회사에 알려야 합니다.
② 계약을 맺은 보험의 목적에 아래와 같은 사실이 생긴 경우에 계약자 또는 피보험자는 정당
한 이유없이 지연되지 않도록 이를 서면으로 회사에 알려야 합니다.
1. 이 계약이 부담하지 않는 사고로 인한 보험의 목적의 일부 또는 전부의 없어짐
2. 다수보험계약을 맺은 경우
③ 제2항 제1호의 경우 회사는 계약자 또는 피보험자와 보험의 목적의 가액을 다시 평가하여
보험가액과 보험가입금액을 변경합니다. 이 경우 회사는 보험가입금액의 변경에 따른 정해
진 보험료를 받거나 돌려 드립니다.
④ 제2항 제2호의 경우 회사는 이 계약을 해지할 수 있습니다. 그러나 계약자 또는 피보험자가
그 사실을 회사에 알린 날로부터 15일 이내에 회사가 이 계약을 해지하지 않은 경우에는
그렇지 않습니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '협정보험가액 특별약관', NULL, '제2조~제4조', '보험가액', 618, 247, 'high', NULL),
