① 회사는 계약자, 피보험자 또는 이들의 대리인이 제4조(알릴 의무)에 정한 알릴 의무를 이행
하지 않았을 때에 이 계약을 해지할 수 있습니다. 그러나 회사가 그 사실을 안 때로부터 1
개월이 지났거나 회사의 과실로 알지 못한 때에는 해지할 수 없습니다.
② 제1항에 의한 계약의 해지는 손해가 생긴 후에 이루어져도 회사는 그 손해를 보상하여 드
리지 않습니다.

제6조 준용규정
