① 이 특별약관이 첨부된 계약에 있어서는 계약체결시 회사와 계약자 또는 피보험자와의 사이
에 보험의 목적을 평가하고 그 금액(이하「평가액」이라 합니다)을 보험증권에 기재합니다.
② 보험의 목적이 건물인 경우의 평가액은 보험의 목적에 전부손해가 생겼을 경우 재조달가액
에 의하여 정합니다.
③ 보험가입금액은 보험증권에 기재한 평가액에 보험증권에 기재된 가입비율을 곱한 금액으로
합니다.

제2조 지급보험금
① 회사는 보통약관 제9조(지급보험금의 계산)의 규정에도 불구하고 보험가입금액을 한도로 하
여 손해액을 전액 지급합니다.
② 보험의 목적이 건물인 경우의 손해액은 그 손해가 생긴 때와 곳에서의 그 보험의 목적의 재
조달가액에 의하여 정합니다.
③ 보험의 목적이 건물인 경우 그 보험의 목적에 대하여 이 특약과 동일한 특약을 첨부하지 않
은 다른 계약이 있을 때에는, 회사는 보통약관 제9조(지급보험금의 계산)의 규정에도 불구
하고 다음 산식에 의하여 계산한 금액을 보험금으로 지급합니다.
지급보험금 = (제1항 및 제2항에 의하여 계산된 손해액) - (다른 계약에 의하여 지급되는 보험금)
다만, 다른 계약이 없는 것으로 하여 계산된 지급책임액을 한도로 합니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '가액협정 특별약관', NULL, '제1조~제2조', '보험의 목적의 평가', 650, 260, 'high', NULL),
    ('KB손해보험_주택종합보험_(주택)_16_제3조제4조', '[KB손해보험 / 주택종합보험_(주택) / 가액협정 특별약관] 제3조~제4조 계약 전 알릴 의무', '[KB손해보험 / 주택종합보험_(주택) / 가액협정 특별약관] 제3조~제4조 계약 전 알릴 의무
① 계약자, 피보험자 또는 이들의 대리인은 제1조 또는 보통약관 제3조(보상하는 손해)의 제1
항에 규정한 평가 또는 재평가시 회사가 평가 또는 재평가를 위하여 필요한 조치사항에 대
하여 아는 사실을 빠짐없이 그대로 회사에 알려야 합니다.
② 제1항의 알릴 의무를 이행하지 않았을 경우에는 회사는 보통약관 제30조(계약의 해지)의 해
지규정에 따라 이 특약을 해지할 수 있습니다.
③ 손해가 발생한 후에 제2항의 해지가 된 경우에도 그 손해에 대하여 제2조(지급보험금) 제1
항, 제2항 및 제6조(용어의 대체)의 규정은 적용하지 않습니다. 만약 제2조(지급보험금) 제
1항, 제2항 및 제6조(용어의 대체)의 규정을 적용하여 보험금을 지급한 때에는 회사는 제2
조(지급보험금) 제1항, 제2항 및 제6조(용어의 대체)의 규정이 없는 것으로 하여 계산된 보
험금과의 차액의 반환을 청구할 수 있습니다.

제4조 계약 후 알릴 의무
① 계약을 맺은 보험의 목적에 아래와 같은 사실이 생겨 보험의 목적의 가액이 뚜렷하게 증가
또는 감소한 경우에는 계약자 또는 피보험자는 이를 정당한 이유없이 지연되지 않도록 서
면으로 회사에 알려야 합니다.
1. 보험의 목적인 건물의 증축, 개축, 일부철거
2. 이 보험에서 부담하지 않는 사고로 인한 보험의 목적의 일부 없어짐
② 제1항의 경우 회사는 계약자 또는 피보험자와 보험의 목적의 가액을 재평가하여 보험가입
금액을 변경합니다. 이 경우 회사는 보험요율의 변경에 따른 정해진 보험료를 받거나 돌려
드리며 받을 보험료에 대하여는 보통약관 제25조(제1회 보험료 등 및 회사의 보장개시)의
제1항에 따릅니다.
③ 제1항의 절차를 게을리 한 경우에, 그 사실이 발생한 때로부터 제2항의 절차가 완료될 때까
지 사이에 발생한 손해에 대하여는 제2조(지급보험금)의 제1항을 적용하지 않습니다. 다만,
감액하는 경우에는 그러하지 않습니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '가액협정 특별약관', NULL, '제3조~제4조', '계약 전 알릴 의무', 987, 394, 'high', NULL),
