이 특별약관에 정하지 않은 사항은 보통약관을 따릅니다.

제6조 용어의 대체
보험의 목적이 건물인 경우 보통약관 규정 중 보험의 목적의 가액 또는 보험가액으로 표시된
것은 보험의 목적의 재조달가액으로 바꿉니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '가액협정 특별약관', NULL, '제5조~제6조', '준용규정', 165, 66, 'high', NULL),
    ('KB손해보험_주택종합보험_(주택)_17_제1조제2조', '[KB손해보험 / 주택종합보험_(주택) / 어린이놀이시설배상책임 특별약관] 제1조~제2조 용어의 정의', '[KB손해보험 / 주택종합보험_(주택) / 어린이놀이시설배상책임 특별약관] 제1조~제2조 용어의 정의
이 특별약관에서는 보통약관 제2조(용어의 정의) 제1호 ‘나‘목, 제2호 ‘가’목 및 ‘나’목을 아래
와 같이 대체하여 적용합니다.
1. 계약 관련 용어
가. 피보험자: 보험사고로 인하여 타인에 대한 법률상 손해배상책임을 부담하는 손해를 입
은 사람(법인인 경우에는 그 이사 또는 법인의 업무를 집행하는 그 밖의 기관)을 말합
니다. 단, "어린이놀이시설 관리주체 위험"의 피보험자는 어린이놀이시설안전관리법 제
2조 제5호에서 정의된 관리주체(용어의 정의 참조요망)로서 보험증권에 피보험자로 기
재된 자를 말합니다.
2. 보상 관련 용어
가. 배상책임: 보험증권상의 보장지역 내에서 보험기간 중에 발생된 보험사고로 인하여 타
인에게 입힌 손해에 대한 법률상의 책임을 말합니다.
나. 보상한도액: 회사와 계약자간에 약정한 금액으로 피보험자가 법률상의 배상책임을 부
담함으로써 입은 손해 중 제6조(보험금 등의 지급한도)에 따라 회사가 책임지는 금액
의 최대한도를 말합니다.

제2조 보상하는 손해
회사는 피보험자가 보험증권상의 보장지역 내에서 보험기간중에 발생된 보험사고(피보험자가
소유, 사용 또는 관리하는 어린이놀이시설(이하 “시설”이라 합니다) 및 그 시설의 용도에 따른
업무(이하 “업무”라 합니다)의 수행으로 생긴 우연한 사고를 말합니다)로 인하여 피해자에게
법률상의 배상책임을 부담함으로써 입은 아래의 손해를 이 약관에 따라 보상하여 드립니다.
1. 피보험자가 피해자에게 지급할 책임을 지는 법률상의 손해배상금
2. 계약자 또는 피보험자가 지출한 아래의 비용
가. 피보험자가 제9조(손해방지의무) 제1항 제1호의 손해의 방지 또는 경감을 위하여 지출
한 필요 또는 유익하였던 비용
나. 피보험자가 제9조(손해방지의무) 제1항의 제2호의 제3자로부터 손해의 배상을 받을 수
있는 그 권리를 지키거나 행사하기 위하여 지출한 필요 또는 유익하였던 비용
【설명】
제3자로부터 손해의 배상을 받을 수 있는 경우에 피보험자가 손해배상청구를 위해 내용증
명, 재산조사, 강제집행 등을 수행하고자 지출한 각종 비용을 의미합니다.
다. 피보험자가 지급한 소송비용, 변호사비용, 중재, 화해 또는 조정에 관한 비용
라. 보험증권상 보상한도액내의 금액에 대한 공탁보증보험료. 그러나 그러한 보증을 제공
할 책임은 부담하지 않습니다.
마. 피보험자가 제10조(손해배상청구에 대한 회사의 해결) 제2항 및 제3항의 회사의 요구
