손해액 ×
다른 계약이 없는 것으로 하여 각각 계산한 보상책임액의 합계액
【예시】
보상책임액의 합계액이 손해액을 초과하는 경우 :
계약A: 보상책임액 1,000만원 / 계약B: 보상책임액 1,000만원 / 손해액 : 1,000만원
→ 계약A보험회사 : 500만원 지급 = 1,000만원 × 1,000만원 / (1,000만원 + 1,000만원)
→ 계약B보험회사 : 500만원 지급 = 1,000만원 × 1,000만원 / (1,000만원 + 1,000만원)
② 이 계약이 의무보험이 아니고 다른 의무보험이 있는 경우에는 다른 의무보험에서 보상되는
금액(피보험자가 가입을 하지 않은 경우에는 보상될 것으로 추정되는 금액)을 차감한 금액
을 손해액으로 간주하여 제1항에 의한 보상할 금액을 결정합니다.
③ 피보험자가 다른 계약에 대하여 보험금 청구를 포기한 경우에도 회사의 제1항에 의한 지급
보험금 결정에는 영향을 미치지 않습니다.', 'KB손해보험', '주택종합보험_(주택)', '동산', '어린이놀이시설배상책임 특별약관', NULL, '제7조~제8조', '의무보험과의 관계', 1019, 407, 'high', NULL),
