합니다.
【보상책임을 지는 한도】
동일한 사고로 이미 지급한 보험금이나 가지급보험금이 있는 경우에는 그 금액을 공제한
액수를 말합니다.
③ 회사가 제1항의 절차에 협조하거나 대행하는 경우에 피보험자는 회사의 요청에 따라 협력
해야 하며, 피보험자가 정당한 이유없이 협력하지 않는 경우에는 그로 말미암아 늘어난 손
해에 대해서 보상하지 않습니다.
④ 회사는 다음의 경우에는 제1항의 절차를 대행하지 않습니다.
1. 피보험자가 피해자에 대하여 부담하는 법률상의 손해배상책임액이 보험증권에 기재된 보
상한도액을 명백하게 초과하는 때
2. 피보험자가 정당한 이유없이 협력하지 않는 때
