안전검사기관
검사기관으로 지정된 자를 말합니다. 신체장해 “신체장해”라 함은 신체의 상해, 질병 및 그로 인한 사망을 말합니다. “재물손해”라 함은 아래와 같습니다. 1) 물리적으로 망그러뜨려진 유체물(有體物)의 직접손해
재물손해
2) 물리적으로 망그러뜨려진 유체물의 사용불능으로 생긴 간접손해
3) 물리적으로 망그러뜨려지지 않은 유체물의 사용불능으로 생긴 간접손해
급격하게 발생하는 것을 포함하여 위험이 서서히, 계속적, 반복적 또는
사고
