1. 계약 관련 용어
가. 피보험자: 보험사고로 인하여 타인에 대한 법률상 손해배상책임을 부담하는 손해를 입
은 사람(법인인 경우에는 그 이사 또는 법인의 업무를 집행하는 그 밖의 기관)을 말합
