6. 피보험자와 타인간에 손해배상에 관한 약정이 있는 경우 그 약정에 의하여 가중된 손해
배상책임. 그러나 약정이 없었더라도 법률규정에 의하여 피보험자가 부담하게 될 배상책
임은 보상합니다.
7. 피보험자가 소유, 점유, 임차, 사용하거나 보호, 관리, 통제(원인에 관계없이 모든 형태의
실질적인 통제행위를 포함합니다)하는 재물이 손해를 입음으로써 그 재물에 대하여 정당
한 권리를 가지는 사람에 대한 손해배상책임
8. 벌과금 및 징벌적 손해에 대한 배상책임
9. 티끌, 먼지, 석면, 분진 또는 소음으로 생긴 손해에 대한 배상책임
10. 전자파, 전자장(EMF)으로 생긴 손해에 대한 배상책임
