경우 계약이 성립한 날로부터 3개월 이내에 이의를 제기하시고 그 사실이 인정되면 납입하신 보험료와 청약일로부터 실
제 지급일까지의 경과기간에 대한 보험계약대출이율을 더한 금액을 환불하여 드립니다. 보험관련 민원상담 및 분쟁조정 안내
보험계약, 보상 관련 및 보험금 지급 등에 관하여 불만사항이 있으실 경우, 저희 회사에 이의를 제기하여 주시면, 신속하
