Ⅲ  보험계약의  일반사항
1.  청약을  철회할  수  있는  권리 보통약관 제20조
일반금융소비자인 계약자는 보험증권을 받은 날부터 15일 이내에 보험계약의 청약을 철회
할 수 있으며, 이 경우 회사는 3영업일 이내에 납입한 보험료를 돌려드립니다.
청약철회 기간
청약일 보험증권을 받은 날 보험증권을 받은 날+15일
! [청약철회가 불가한 경우]
① 청약일부터 30일(만65세 이상 보험계약자&전화로 체결한 계약의 경우 45일)을
주의
초과한 경우
② 회사가 건강상태 진단을 지원하는 계약, 보험기간이 90일 이내인 계약 또는 전문
금융소비자가 체결한 계약
2.  보험계약을  취소할  수  있는  권리 보통약관 제21조
보험계약자는 다음에서 계약이 성립한 날부터 3개월 이내에 계약을 취소할 수 있습니다.
• 보험계약을 청약할 때 보험약관 및 보험계약자 보관용 청약서를 전달받지 못한 경우
• 보험약관의 중요내용을 설명 받지 못한 경우
• 보험계약자가 청약서에 자필서명을 하지 않은 경우
<계약 취소 시 지급하는 금액>
납입한 보험료 + 이자
