3.  보험계약의  무효 보통약관 제22조
보험회사는 다음의 경우 보험계약을 무효로 하며, 이미 납입한 보험료를 돌려드립니다.
• 타인의 사망을 보험금 지급사유로 하는 보험계약에서 피보험자의 서면 동의를 얻지 않은 경우
• 만 15세 미만자, 심신상실자 또는 심신박약자의 사망을 보험금 지급사유(피보험자 지정)로 한
경우
• 보험계약 체결 시 계약에서 정한 피보험자의 나이에 미달되었거나 초과되었을 경우
4.  보험계약前  알릴의무  및  위반시효과 보통약관 제15조, 제17조
보험계약자 또는 피보험자는 보험계약을 청약할 때 청약서의 질문사항(중요사항)에 대하여
사실대로 알려야 합니다.
고의 또는 중과실로 계약 해지 가능
계약자
사실과 다르게 알린 경우 (회사)
또는
피보험자 보장 제한 가능
(회사)
!
① 청약서의 질문사항에 대하여 보험설계사에게만 구두로 알렸을경우 보험계약前 알릴
의무를 이행한 것으로 볼 수 없습니다.
