② 전화 등 통신수단을 통한 보험계약의 경우 보험회사 상담원의 질문이 청약서의 질
문사항을 대신하므로 상담원의 질문에 사실대로 답변하여야 합니다.
A씨는 고지혈증, 당뇨병으로 90일간 투약처방 받은 사실을 보험설계사에게만 알려주고, 청
약서에 기재하지 않은 채 ○○질병보험에 가입하였으며, 가입 이후 1년간 당뇨병으로 통원
민원사례 치료를 받아 보험금을 청구
➡ 보험회사는 보험계약이 해지됨과 동시에 보험금 지급이 어려움을 안내
[대법원 2007.6.28.선고 2006다59837]
일반적으로 보험설계사는 독자적으로 보험회사를 대리하여 보험계약을 체결할 권한
법률지식 이나 고지의무를 수령할 권한이 없음
5.  보험계약後 알릴  의무  및  위반시효과 보통약관 제16조, 제17조
보험계약자 등은 피보험자의 직업·직무변경 등이 발생한 경우 지체없이 보험회사에 알려야
하며, 이를 위반하는 경우 보험금 지급이 제한될 수 있습니다.
! 보험회사는 피보험자의 직업·직무 변경 등으로
① 위험이 감소한 경우 보험료를 감액하고 정산금액을 환급하여 드리며,
주의
② 위험이 증가한 경우 보험료가 증액되고 정산금액의 추가 납입이 필요할 수 있습니
다.
