용 사실을 보험회사에 알리지 않은 경우 보험금 지급이 제한될 수 있습니다.
6.  보험료  납입연체  및  보험계약의  해지 보통약관 제34조
보험료 납입이 연체 중인 경우 보험회사는 납입을 독촉하는 안내를 하며, 납입최고(독촉) 기간
내에 보험료를 납입하지 않으면 보험계약이 해지됩니다.
*납부최고(독촉)기간:14일 이상(보험기간 1년 미만인 경우 7일 이상)
