7.  해지된  보험계약의  부활(효력회복) 보통약관 제35조
보험료 납입연체로 보험계약이 해지되었으나 해약환급금을 받지 않은 경우 해지된 날부터 3년
이내에 보험계약의 부활(효력회복)을 청약할 수 있습니다.
! 보험회사는 피보험자의 건강상태, 직업 등에 따라 승낙여부를 결정하며, 부활(효력회복)
을 거절하거나 보장의 일부를 제한할 수 있습니다. 이 때 회사는 해지 전 발생한 보험
